/* ★ v251: 自定义调色板（ST/LM/RS/V/I/P），COL 页直接编辑 */
static uint16_t cfg_col[6] = { 0xFA2A, 0x5E5B, 0xEF9E, 0xEF9E, 0xEF9E, 0xEF9E };
static uint8_t cfg_theme = 0;
static void apply_theme(void)
{
    switch (cfg_theme) {
    case 1:  /* ICE */
        C_ST=0x07FF; C_LM=0x04FF; C_RS=0x7BEF; C_V=0xF800;
        C_I=0xC618; C_P=0xFC06; C_TMP=0xEF9E; break;
    case 2:  /* AMBER */
        C_ST=0xFD20; C_LM=0xFFE0; C_RS=0x7BEF; C_V=0xF800;
        C_I=0xC618; C_P=0xFC06; C_TMP=0xFC00; break;
    case 3:  /* CUSTOM (COL) */
        C_ST=cfg_col[0]; C_LM=cfg_col[1]; C_RS=cfg_col[2];
        C_V=cfg_col[3]; C_I=cfg_col[4]; C_P=cfg_col[5];
        C_TMP=0xEF9E; break;
    default: /* FACTORY */
        C_ST=0xFA2A; C_LM=0x5E5B; C_RS=0xEF9E; C_V=0xEF9E;
        C_I=0xEF9E; C_P=0xEF9E; C_TMP=0xEF9E; break;
    }
}

