static int text_w(const char *s) { int n = 0; while (s[n]) n++; return n ? 6 * n - 1 : 0; }
static void text_big_right(int rx,int y,const char*s,uint16_t c,int sc){ int w=text_w(s)*sc; lcd_text_big(rx-w+1,y,s,c,sc); }
static void text_right(int rx, int y, const char *s, uint16_t c) { lcd_text(rx - text_w(s), y, s, c); }
static void draw_icon16(int x, int y, int idx, uint16_t c)
{
    const uint8_t *b = ICONS[idx & 7];
    for (int r = 0; r < 16; r++) {
        uint16_t bits = (uint16_t)((b[r * 2] << 8) | b[r * 2 + 1]);
        if (!bits) continue;
        for (int col = 0; col < 16; col++)
            if (bits & (0x8000 >> col)) lcd_px(x + col, y + r, c);
    }
}
static void draw_icon12(int x, int y, int idx, uint16_t c)
{
    const uint8_t *b = SET_ICONS[idx % 10];
    for (int r = 0; r < 12; r++) {
        uint16_t bits = (uint16_t)((b[r * 2] << 8) | (b[r * 2 + 1] & 0xF0));
        if (!bits) continue;
        for (int col = 0; col < 12; col++)
            if (bits & (0x8000 >> col)) lcd_px(x + col, y + r, c);
    }
}
/* ARENA MK II header: code + action hint + index + back chevron */
static void draw_header(const char *code, const char *hint, const char *right)
{
    lcd_fill(0, 0, 2, 8, C_OK);
    lcd_text(4, 1, code, C_OK);
    if (hint && hint[0]) lcd_text(32, 1, hint, C_DIM);
    if (right && right[0]) text_right(146, 1, right, C_DIM);
    lcd_text(153, 1, "<", C_DIM);
    lcd_fill(0, 8, 160, 1, C_TRACK);
    lcd_fill(0, 8, 24, 1, C_OK);
}
static void draw_page_header(const char *title, const char *right) { draw_header(title, (const char *)0, right); }

static void draw_meter(int x, int y, int w, int h, int pct, uint16_t fill, uint16_t track)
{
    if (pct < 0) pct = 0;
    if (pct > 100) pct = 100;
    lcd_fill(x, y, w, h, track);
    int fw = w * pct / 100;
    if (fw) lcd_fill(x, y, fw, h, fill);
    for (int k = 1; k < 10; k++) lcd_fill(x + k * w / 10, y, 1, h, C_BG);
}

static void draw_diamond(int cx, int cy, int r, uint16_t c)
{
    for (int i = 0; i <= r; i++) {
        lcd_px(cx + i, cy - r + i, c); lcd_px(cx + i + 1, cy - r + i, c);
        lcd_px(cx - i, cy - r + i, c); lcd_px(cx - i - 1, cy - r + i, c);
        lcd_px(cx + i, cy + r - i, c); lcd_px(cx + i + 1, cy + r - i, c);
        lcd_px(cx - i, cy + r - i, c); lcd_px(cx - i - 1, cy + r - i, c);
    }
}

static void draw_line(int x0, int y0, int x1, int y1, uint16_t c)
{
    int dx = x1 - x0, sx = dx < 0 ? -1 : 1; if (dx < 0) dx = -dx;
    int dy = y1 - y0, sy = dy < 0 ? -1 : 1; if (dy < 0) dy = -dy;
    int err = dx - dy;
    for (;;) {
        lcd_px(x0, y0, c);
        if (x0 == x1 && y0 == y1) break;
        int e2 = 2 * err;
        if (e2 > -dy) { err -= dy; x0 += sx; }
        if (e2 < dx)  { err += dx; y0 += sy; }
    }
}
static void fill_chamfer(int x, int y, int w, int h, int cut, uint16_t c)
{
    for (int r = 0; r < h; r++) {
        int inset = 0;
        if (r < cut) inset = cut - r;
        int rb = h - 1 - r;
        if (rb < cut && cut - rb > inset) inset = cut - rb;
        lcd_fill(x + inset, y + r, w - 2 * inset, 1, c);
    }
}
static void draw_degree(int x, int y, uint16_t c)
{
    lcd_fill(x, y, 2, 2, c);
    lcd_text(x + 3, y - 2, "C", c);
}

static void draw_val_unit(int rx, int y, const char *num, const char *unit, uint16_t nc, uint16_t uc)
{
    int uw = (unit && unit[0]) ? text_w(unit) : 0;
    if (uw) { text_right(rx, y, unit, uc); text_right(rx - uw - 1, y, num, nc); }
    else text_right(rx, y, num, nc);
}

static int lum565(uint16_t c)
{
    int r = ((c >> 11) & 31) * 255 / 31;
    int g = ((c >> 5) & 63) * 255 / 63;
    int b = (c & 31) * 255 / 31;
    return (r * 299 + g * 587 + b * 114) / 1000;
}

static uint16_t contrast565(uint16_t c)
{
    return (lum565(c) > 140) ? C_BG : C_BONE;
}

/* 自定义调色板可能把数值色选到接近黑；主界面关键读数强制回退到可见色 */
static uint16_t readable565(uint16_t c, uint16_t fallback)
{
    return (lum565(c) < 18) ? fallback : c;
}

