static int set_view_of(int sel)
{
    if (sel == SET_N - 1) return SET_N - 2;
    if (sel >= 7 && sel <= 9) return sel;   /* 06 已从界面移除，避免露出旧 6 */
    int base = (sel / 2) * 2;
    if (base == 6) base = 7;
    return base;
}

/* 缓出曲线：用于整页擦除 / 温度滚动 */
static int ease_out_pm(uint32_t el, uint32_t dur)
{
    if (el >= dur) return 1000;
    uint32_t p = el * 1000u / dur;
    uint32_t q = 1000u - p;
    return (int)(1000u - (q * q * q) / 1000000u);
}
/* smoothstep 缓入缓出：用于整页滑动/长距离指示器，首尾都不突兀 */
static int ease_io_pm(uint32_t el, uint32_t dur)
{
    if (el >= dur) return 1000;
    uint32_t p = el * 1000u / dur;
    uint32_t a = 3u * p * p / 1000u;          /* 3p² */
    uint32_t b = 2u * p * p * p / 1000000u;   /* 2p³ */
    return (int)(a - b);
}
/* A 方案：前缘快出、后缘延迟，选中块在两格之间拉出连接带 */
static int stretch_lead(uint32_t el)  { return ease_out_pm(el, UI_STRETCH_MS); }
static int stretch_trail(uint32_t el)
{
    if (el <= UI_STRETCH_DELAY) return 0;
    return ease_out_pm(el - UI_STRETCH_DELAY, UI_STRETCH_MS - UI_STRETCH_DELAY);
}
static int stretch_view(uint32_t el)  { return ease_io_pm(el, UI_STRETCH_MS); }
static uint32_t anim_el(uint32_t t0, uint32_t now)
{
    if (!t0) return UI_STRETCH_MS;
    uint32_t el = now - t0;
    return (el > UI_STRETCH_MS) ? UI_STRETCH_MS : el;
}
static void set_step(int d)
{
    if (!set_edit) {
        do {
            set_sel = (set_sel + ((d < 0) ? (SET_N - 1) : 1)) % SET_N;
        } while (set_sel == 6);
        set_pos_from = set_pos_to = (int16_t)(set_sel * 1000);
        set_view_from = set_view_to = (int16_t)(set_view_of(set_sel) * 1000);
        set_anim_t0 = 0;
        return;
    }
    set_flash_t0 = millis();
    switch (set_sel) {
    case 0: cfg_bright += (d > 0) ? 1 : -1; if (cfg_bright < 5) cfg_bright = 5; if (cfg_bright > 100) cfg_bright = 100; break;
    case 1: cfg_rot_mode = (uint8_t)((cfg_rot_mode + ((d > 0) ? 1 : 2)) % 3); break;
    case 2: sleep_mode = (uint8_t)((sleep_mode + ((d > 0) ? 1 : 2)) % 3); break;
    case 3: cfg_idle_s += (d > 0) ? 1 : -1; if (cfg_idle_s < 1) cfg_idle_s = 1;   /* ★ v198: 说明书 步进1，1-250s */ if (cfg_idle_s > 250) cfg_idle_s = 250; break;
    case 4: cfg_pause_s += (d > 0) ? 1 : -1; if (cfg_pause_s < 1) cfg_pause_s = 1;   /* ★ v198: 步进1 */ if (cfg_pause_s > 250) cfg_pause_s = 250; break;
    case 5: cfg_sleep_min += (d > 0) ? 1 : -1; if (cfg_sleep_min < 1) cfg_sleep_min = 1; if (cfg_sleep_min > 250) cfg_sleep_min = 250; break;
    case 6: cfg_logi = cfg_logi ? 0 : 1; break;
    case 7: cfg_motion_th += (d > 0) ? 5 : -5; if (cfg_motion_th < 5) cfg_motion_th = 5; if (cfg_motion_th > 100) cfg_motion_th = 100; break;
    case 8: cfg_boot_anim = cfg_boot_anim ? 0 : 1; break;
    case 9: cfg_boot_heat = cfg_boot_heat ? 0 : 1; break;
    case 10: fly_sel = (uint8_t)((fly_sel + (d > 0 ? 1 : 3)) % 4); break;   /* 退出编辑时提交 */
    case 11: cfg_preset[preset_edit_i] += (d > 0) ? 5 : -5;
             if (cfg_preset[preset_edit_i] < TEMP_MIN_C) cfg_preset[preset_edit_i] = TEMP_MIN_C;
             if (cfg_preset[preset_edit_i] > TEMP_MAX_C) cfg_preset[preset_edit_i] = TEMP_MAX_C;
             settings_dirty(); break;   /* ★ v210: 常用温度 ±5 */
    default: break;
    }
    settings_dirty();
}

/* ★ v248: PID 页 —— 未编辑时移动选中格；编辑时按加速步进调参 */
static void pid_ui_step(int d)
{
    if (pid_test_view) return;
    if (!pid_edit) {
        pid_sel = (pid_sel + (d > 0 ? 1 : PID_N - 1)) % PID_N;
        pid_pos_from = pid_pos_to = (int16_t)(pid_sel * 1000);
        pid_view_from = pid_view_to = (int16_t)(pid_view_of(pid_sel) * 1000);
        pid_anim_t0 = 0;
        return;
    }
    uint32_t now = millis();
    if (pid_adj_t == 0 || now - pid_adj_t > 25u) pid_adj_run = 0;
    else if (pid_adj_run < 100u) pid_adj_run++;
    pid_adj_t = now;
    int mul = (pid_adj_run > 25u) ? 20 : (pid_adj_run > 10u) ? 5 : 1;

    if (pid_sel == 0) {
        int v = (int)(pid_kp * PID_KP_SCALE + 0.5f) + d * mul;  /* 显示 0.01/步 */
        if (v < 0) v = 0;
        if (v > 9999) v = 9999;
        pid_kp = (float)v / PID_KP_SCALE;
    } else if (pid_sel == 1) {
        int v = (int)(pid_ki * PID_KI_SCALE + 0.5f) + d * mul;  /* 显示 0.001/步 */
        if (v < 0) v = 0;
        if (v > 9999) v = 9999;
        pid_ki = (float)v / PID_KI_SCALE;
    } else if (pid_sel == 2) {
        int v = (int)(pid_kd * PID_KD_SCALE + 0.5f) + d * mul;  /* 显示 0.01/步 */
        if (v < 0) v = 0;
        if (v > 9999) v = 9999;
        pid_kd = (float)v / PID_KD_SCALE;
    } else if (pid_sel == 3) {
        target_c += d * 5 * mul;
        if (target_c < TEMP_MIN_C) target_c = TEMP_MIN_C;
        if (target_c > TEMP_MAX_C) target_c = TEMP_MAX_C;
    }
    settings_dirty();
    ui_dirty = 1;
}

/* ★ v251: COL 页 —— 未编辑时切换 6 个颜色项；编辑时调 R/G/B 通道 */
static void col_step(int d)
{
    if (!col_edit) {
        col_sel = (uint8_t)((col_sel + (d > 0 ? 1 : 5)) % 6);
        return;
    }
    uint32_t now = millis();
    if (col_adj_t == 0 || now - col_adj_t > 25u) col_adj_run = 0;
    else if (col_adj_run < 100u) col_adj_run++;
    col_adj_t = now;
    int mul = (col_adj_run > 25u) ? 8 : (col_adj_run > 10u) ? 4 : 1;

    uint16_t c = cfg_col[col_sel];
    int r = (c >> 11) & 31, g = (c >> 5) & 63, b = c & 31;
    if (col_ch == 0) { r += d * mul; if (r < 0) r = 0; if (r > 31) r = 31; }
    else if (col_ch == 1) { g += d * mul; if (g < 0) g = 0; if (g > 63) g = 63; }
    else { b += d * mul; if (b < 0) b = 0; if (b > 31) b = 31; }
    cfg_col[col_sel] = (uint16_t)((r << 11) | (g << 5) | b);
    cfg_theme = 3;
    apply_theme();
    settings_dirty();
    ui_dirty = 1;
}

/* ---- 设置保存（v19 + v136 校准打包） ---- */
static uint8_t settings_save_now(void)
{
    settings_t st;
    st.magic = 0x50443235u;
    st.target_c = target_c;
    st.limit_pct = limit_pct;
    st.pdo_gear = pdo_gear;
    {
        uint32_t r = 0x80000000u;
        for (int k = 0; k < 6; k++) r |= ((uint32_t)((cal_delta[k] + 16) & 0x1F)) << (k * 5);
        st.reserved = r;
    }
    st.checksum = st.magic ^ (uint32_t)target_c ^ (uint32_t)limit_pct ^ (uint32_t)pdo_gear;
    /* ★ v211: 扩展字段持久化 */
    st.ext_valid = 0x45585431u;
    st.misc_a = ((uint32_t)cfg_bright & 0xFFu)
              | ((uint32_t)cfg_rot_mode & 3u) << 8
              | ((uint32_t)sleep_mode & 3u) << 10
              | ((uint32_t)cfg_logi & 1u) << 12
              | ((uint32_t)cfg_boot_heat & 1u) << 13
              | ((uint32_t)cfg_boot_anim & 1u) << 14
              | ((uint32_t)fly_enable & 1u) << 15
              | ((uint32_t)cfg_motion_th & 0xFFu) << 16;
    st.misc_b = ((uint32_t)cfg_idle_s & 0xFFu)
              | ((uint32_t)cfg_pause_s & 0xFFu) << 8
              | ((uint32_t)cfg_sleep_min & 0xFFu) << 16
              | ((uint32_t)cfg_theme & 3u) << 24
              | ((uint32_t)fly_dur & 1u) << 29
              | (1u << 26) | (1u << 27) | (1u << 28);   /* v233: 默认值迁移已完成 */
    st.preset01 = ((uint32_t)cfg_preset[0] & 0xFFFFu) | ((uint32_t)cfg_preset[1] & 0xFFFFu) << 16;
    st.preset2 = (uint32_t)cfg_preset[2] & 0xFFFFu;
    st.ext_chk = st.ext_valid ^ st.misc_a ^ st.misc_b ^ st.preset01 ^ st.preset2;
    st.pid_p100  = (uint32_t)(int)(pid_kp * PID_KP_SCALE + 0.5f);
    st.pid_i1000 = (uint32_t)(int)(pid_ki * PID_KI_SCALE + 0.5f);
    st.pid_d100  = (uint32_t)(int)(pid_kd * PID_KD_SCALE + 0.5f);
    st.pid_tag   = 0x504B0000u
                 | ((st.pid_p100 ^ st.pid_i1000 ^ st.pid_d100 ^ 0x504Bu) & 0xFFFFu);
    st.col01 = ((uint32_t)cfg_col[0] & 0xFFFFu) | ((uint32_t)cfg_col[1] << 16);
    st.col23 = ((uint32_t)cfg_col[2] & 0xFFFFu) | ((uint32_t)cfg_col[3] << 16);
    st.col45 = ((uint32_t)cfg_col[4] & 0xFFFFu) | ((uint32_t)cfg_col[5] << 16);
    st.col_tag = 0x434F0000u
               | ((st.col01 ^ st.col23 ^ st.col45) & 0xFFFFu);
    return flash_settings_write(&st);
}
static void settings_dirty(void) { save_at = millis() + 333u; settings_key_dirty = 1; }   /* 2s 兜底；松手会立即保存 */

/* ★ v216: RST 页恢复出厂默认 */
static void settings_defaults(void)
{
    target_c = 300;
    limit_pct = 25;
    pdo_gear = 1; pdo_sel = 1;
    for (int i = 0; i < 6; i++) cal_delta[i] = 0;
    cfg_bright = 100;
    cfg_rot_mode = 0;
    sleep_mode = 1;
    cfg_idle_s = 30;
    cfg_pause_s = 30;
    cfg_sleep_min = 5;
    cfg_logi = 0;
    cfg_motion_th = 30;
    cfg_boot_anim = 1;
    cfg_boot_heat = 0;
    fly_enable = 0;
    fly_dur = 0;
    cfg_preset[0] = 320; cfg_preset[1] = 350; cfg_preset[2] = 380;
    preset_idx = 0;
    pid_set_defaults();
    pid_sel = 0; pid_edit = 0; pid_test_view = 0;
    cfg_col[0]=0xFA2A; cfg_col[1]=0x5E5B; cfg_col[2]=0xEF9E;
    cfg_col[3]=0xEF9E; cfg_col[4]=0xEF9E; cfg_col[5]=0xEF9E;
    col_sel = 0; col_edit = 0; col_ch = 0;
    cfg_theme = 0;
    apply_theme();
    set_sel = 0; set_edit = 0;
    settings_save_now();
}

/* ★ v217: 统一翻页（整页滑动 + 上一帧快照合成） */
static void ui_go(int np, int dir)
{
    if (np == page) return;
    /* ★ v227: 任何“主界面 → 子页/菜单”的跳转都立即停热，返回主界面也不恢复 */
    if (page == 0 && np != 0) {
        heat_on = 0; tip_paused = 0; duty_now = 0; pwm_set(0);
    }
    if (np == 0) {
        heat_on = 0; tip_paused = 0; duty_now = 0; pwm_set(0);
        pid_i = 0; last_err = 0;
        main_temp_snap();
        main_click_guard_until = millis() + 40u;
    }
    if (page == 12) set_edit = 0;
    if (page == 14) {   /* ★ v248: 离开 PID 页立即停热，避免菜单里继续加热 */
        pid_edit = 0; pid_test_view = 0;
        heat_on = 0; tip_paused = 0; duty_now = 0; pwm_set(0);
    }
    if (np == 14) { pid_sel = 0; pid_edit = 0; pid_saved_t0 = 0; pid_test_view = 0; }
    if (np == 16) info_sel = 0;
    if (page == 15) col_edit = 0;
    if (np == 15) {
        /* ★ v251: 首次进 COL 时把当前主题色复制为自定义调色板，编辑即生效 */
        if (cfg_theme != 3) {
            cfg_col[0]=C_ST; cfg_col[1]=C_LM; cfg_col[2]=C_RS;
            cfg_col[3]=C_V;  cfg_col[4]=C_I;  cfg_col[5]=C_P;
            cfg_theme = 3;
            apply_theme();
            settings_dirty();
        }
        col_sel = 0; col_edit = 0; col_ch = 0;
    }
    page = np;
    bc_hold_hint = 0;
    /* v329: 入场先不画红色选中格，落位后再点亮；方向保持与其他页一致 */
    pdo_hl_pending = (uint8_t)(np == 1);
    pdo_hl_hold = (uint8_t)(np == 1);
    pdo_hl_done = 0;
    pdo_hl_t0 = 0;
    ui_slide = (uint8_t)(dir < 0 ? 2 : 1);
    ui_slide_ready = 0;
    ui_slide_pm = 0;
    ui_slide_boot = 0;
    ui_anim_t0 = millis();
    ui_dirty = 1;
}
static int pdo_cell_x(int i) { return 2 + (i % 2) * 80; }
static int pdo_cell_y(int i) { return 9 + (i / 2) * 9; }
static void menu_move(int d)
{
    int old = menu_sel;
    if (d < 0) { if (menu_sel > 0) menu_sel--; }
    else       { if (menu_sel < 6) menu_sel++; }
    if (menu_sel != old) {
        menu_pos_from = (int16_t)(old * 1000);
        menu_pos_to = (int16_t)(menu_sel * 1000);
        menu_view_from = (int16_t)(menu_view_of(old) * 1000);
        menu_view_to = (int16_t)(menu_view_of(menu_sel) * 1000);
        menu_anim_t0 = 0;
        ui_dirty = 1;
    }
}
static void pdo_move(int d)
{
    int old = pdo_sel;
    pdo_sel = (pdo_sel + ((d > 0) ? 1 : 5)) % 6;
    pdo_x_from = (int16_t)pdo_cell_x(old);
    pdo_y_from = (int16_t)pdo_cell_y(old);
    pdo_x_to = (int16_t)pdo_cell_x(pdo_sel);
    pdo_y_to = (int16_t)pdo_cell_y(pdo_sel);
    pdo_anim_t0 = millis();
    pdo_diag_first = 1;
    pdo_hl_pending = 0;
    pdo_hl_hold = 0;
    pdo_hl_done = 0;
    pdo_hl_t0 = 0;
    ui_dirty = 1;
}

