/* ---- 采样常量 ---- */
#define WIN_PH 32
#define TEMP_RAW_VALID_MAX 3100  /* 温度换算有效上限 */
#define TIP_RAW_THRESHOLD  4000  /* PD245 设计基线：raw >= 4000 判无头/NoIron */
