/* ---- 温度换算表 + 分段校准（v113/v136） ---- */
static const uint16_t TEMP_POINT_C[6] = {25, 100, 200, 300, 400, 450};
/* PD245 设计基线温度节点（0x0800CE38）：10/475/1115/1785/2450/2775 → 25/100/200/300/400/450 */
static const uint16_t TEMP_POINT_RAW[6] = {10, 475, 1115, 1785, 2450, 2775};
static float adc_to_c(uint16_t raw)
{
    if (raw > TEMP_RAW_VALID_MAX) return 0.0f;
    if (raw > TEMP_POINT_RAW[5]) raw = TEMP_POINT_RAW[5];   /* 设计基线对 2775..3100 夹到 450°C */
    for (int i = 4; i >= 0; i--) {
        if (raw >= TEMP_POINT_RAW[i]) {
            int32_t tc = (int32_t)TEMP_POINT_C[i] +
                (int32_t)(TEMP_POINT_C[i+1] - TEMP_POINT_C[i]) * (raw - TEMP_POINT_RAW[i]) /
                (TEMP_POINT_RAW[i+1] - TEMP_POINT_RAW[i]);
            int32_t d0 = (int32_t)cal_delta[i];
            int32_t d1 = (int32_t)cal_delta[i + 1];
            tc += d0 + (d1 - d0) * (int32_t)(raw - TEMP_POINT_RAW[i]) / (int32_t)(TEMP_POINT_RAW[i + 1] - TEMP_POINT_RAW[i]);
            if (tc < 0) tc = 0;
            if (tc > 999) tc = 999;
            return (float)tc;
        }
    }
    return (float)TEMP_POINT_C[0];
}

static uint16_t last_good_temp = 25;

/* PD245 是独立 TEMP 线，但 TEMP 与加热回路共地：PWM 导通拍会把开关
 * 噪声叠进 TEMP（黑匣子实测 raw 抖动 77 LSB，关断拍仅 25 LSB）。
 * 采样前短暂关断 PWM，等输出级完全关断后再采 4 次。 */
static uint16_t adc_temp_win(void)
{
    uint32_t ccr = TIM2->CCR4;
    if (ccr) {
        TIM2->CCR4 = 0;
        uint16_t c0 = (uint16_t)TIM2->CNT;
        while (((uint16_t)(TIM2->CNT - c0) & 0xFFFFu) < 64u) ;  /* ~8us @8MHz */
    }
    uint32_t s = 0;
    for (int i = 0; i < 4; i++) s += adc_temp();
    if (ccr) TIM2->CCR4 = ccr;
    return (uint16_t)(s / 4);
}

