{
    hist[hist_i] = nv; hist_i = (hist_i + 1) & 7;
    if (g_hist_n < 8) g_hist_n++;
    uint16_t s = 0; for (int i = 0; i < 8; i++) s += hist[i];
    return (uint16_t)(s / 8);
}
