/* ---- 按键动作 ---- */
static void act_temp_set(int v) { if (v < TEMP_MIN_C) v = TEMP_MIN_C; if (v > TEMP_MAX_C) v = TEMP_MAX_C; target_c = v; settings_dirty(); }   /* ★ v210 */
static void act_temp_dec(void) { target_c -= TEMP_STEP; if (target_c < TEMP_MIN_C) target_c = TEMP_MIN_C; settings_dirty(); }
static void act_temp_inc(void) { target_c += TEMP_STEP; if (target_c > TEMP_MAX_C) target_c = TEMP_MAX_C; settings_dirty(); }
static void act_limit_dec(void) { limit_pct -= 1; if (limit_pct < 1) limit_pct = 1; settings_dirty(); }
static void act_limit_inc(void) { limit_pct += 1; if (limit_pct > 100) limit_pct = 100; settings_dirty(); }
static void act_left(void)  { if (page == 0) act_temp_dec(); else if (page == 2) act_limit_dec(); else if (page == 10) menu_move(-1); else if (page == 13) { if (cal_adj) { if (cal_delta[cal_idx] > -15) { cal_delta[cal_idx]--; settings_dirty(); } } else { cal_idx = (cal_idx + 5) % 6; } } else if (page == 12) { set_step(-1); } else if (page == 14) { pid_ui_step(-1); } else if (page == 15) { col_step(-1); } else if (page == 16) { info_sel = (info_sel + INFO_N - 1) % INFO_N; } }
static void act_right(void) { if (page == 0) act_temp_inc(); else if (page == 2) act_limit_inc(); else if (page == 10) menu_move(1); else if (page == 13) { if (cal_adj) { if (cal_delta[cal_idx] < 15) { cal_delta[cal_idx]++; settings_dirty(); } } else { cal_idx = (cal_idx + 1) % 6; } } else if (page == 12) { set_step(1); } else if (page == 14) { pid_ui_step(1); } else if (page == 15) { col_step(1); } else if (page == 16) { info_sel = (info_sel + 1) % INFO_N; } }

