static int disp_digit(int v, int pos)
{
    if (v < 0) return -1;
    if (pos == 0) return (v >= 100) ? v / 100 : -1;
    if (pos == 1) return (v >= 10) ? (v / 10) % 10 : -1;
    return v % 10;
}

static int temp_roll_update(int tgt, uint32_t now)
{
    if (!disp_roll_init) { disp_val = tgt; disp_roll_to = tgt; disp_roll_init = 1; }
    if (disp_roll_active && now - disp_roll_t0 >= disp_roll_dur) {
        disp_val = disp_roll_to;
        disp_roll_active = 0;
    }
    if (!disp_roll_active && tgt != disp_val) {
        int diff = tgt - disp_val;
        int ad = diff < 0 ? -diff : diff;
        int dtt = tgt - target_c; if (dtt < 0) dtt = -dtt;
        int near_target = (dtt <= 3);
        /* v244: 到温后 ±1℃ 不刷新，避免 PID/ADC 噪声让数字一直跳；
         * ★ v255: 到温/常温每步 330ms，至少隔 330ms 再起下一次滚动
         * ★ v015: 但不能把显示冻在 target-1；滤波值正好等于目标时允许贴上去，
         *   贴到目标后再用 ±1℃ 死区防抖 */
        if (near_target && ad < 2 && (tgt != target_c || disp_val == target_c))
            return disp_val;
        if (near_target && now - disp_roll_last < 55u) return disp_val;
        int step = (ad > 20) ? (ad + 9) / 10 : 1;
        int nxt = disp_val + (diff > 0 ? step : -step);
        if ((diff > 0 && nxt > tgt) || (diff < 0 && nxt < tgt)) nxt = tgt;
        disp_roll_to = nxt;
        /* ★ v257: 室温 400ms/步（不管是否在加热）；到温 330ms/步；离目标较远 200ms/步 */
        int ambient = (tgt <= 60);
        disp_roll_dur = ambient ? 67u : (near_target ? 55u : 33u);
        disp_roll_t0 = now;
        disp_roll_last = now;
        disp_roll_active = 1;
    }
    if (tgt < 0 || disp_val < 0) { disp_val = tgt; disp_roll_active = 0; }
    return disp_val;
}

static void draw_temp_roll(int x0, int y, int dw, int dh, int th, uint16_t col)
{
    if (!disp_roll_active) {
        lcd_seg7(x0, y, disp_val, col, dw, dh, th);
        return;
    }
    int off = ease_io_pm(millis() - disp_roll_t0, disp_roll_dur) * dh / 1000;
    int area_w = 3 * (dw + 2) - 2;
    int d0 = disp_val, d1 = disp_roll_to;
    int block = ((d0 < 100) != (d1 < 100));
    if (!block) { int diff = d1 - d0; if (diff < 0) diff = -diff; block = (diff > 20); }
    lcd_set_clip(x0, y, x0 + area_w - 1, y + dh - 1);
    for (int i = 0; i < 3; i++) {
        int xd = x0 + i * (dw + 2);
        int od = disp_digit(d0, i), nd = disp_digit(d1, i);
        if (block) {
            if (od >= 0) lcd_seg7_digit(xd, y - off, od, col, dw, dh, th);
            if (nd >= 0) lcd_seg7_digit(xd, y + dh - off, nd, col, dw, dh, th);
        } else if (od == nd) {
            if (od >= 0) lcd_seg7_digit(xd, y, od, col, dw, dh, th);
        } else {
            if (od >= 0) lcd_seg7_digit(xd, y - off, od, col, dw, dh, th);
            if (nd >= 0) lcd_seg7_digit(xd, y + dh - off, nd, col, dw, dh, th);
        }
    }
    lcd_set_clip(0, 0, 159, 39);
}

static uint16_t temp_state_color(int t)
{
    if (dev_state == DS_NO_TIP) return C_TMP;
    if (heat_on) {
        if (t < target_c - 4) return C_OK;     /* 升温中：信号橙 */
        return C_TMP;                          /* 到温/保温：骨白 */
    }
    if (t > 60) return 0x04FF;                 /* 关热后仍热：冷蓝 */
    return C_TMP;
}

static void hex4(char *p, uint16_t v)
{
    const char *h = "0123456789ABCDEF";
    p[0] = h[(v >> 12) & 15];
    p[1] = h[(v >> 8) & 15];
    p[2] = h[(v >> 4) & 15];
    p[3] = h[v & 15];
}

static void draw_bb_id(uint64_t crc)
{
    uint64_t id = crc & 0xFFFFFFFFFFFFull;   /* 48-bit display code */
    char b[15];
    hex4(b, (uint16_t)(id >> 32));
    b[4] = '-';
    hex4(b + 5, (uint16_t)(id >> 16));
    b[9] = '-';
    hex4(b + 10, (uint16_t)id);
    b[14] = 0;
    lcd_fill(0, 33, 160, 7, C_BG);
    int w = 14 * 6 - 1;
    int x = (160 - w) / 2;
    lcd_text(x, 33, b, 0x04FF);
}

static void draw_main(float cur, int st)
{
    char b[24], stb[8], lmb[8], rsb[10], vb[10], ib[12], pb[12], pc[8];
    uint32_t now = millis();
    int update_ip = (snap_t0 == 0) || (now - snap_t0 >= 25u);
    int update_v  = (snap_v_t0 == 0) || (now - snap_v_t0 >= 100u);
    int v10, i_ma, out_pct;
    uint16_t rs_disp;
    if (update_ip) {
        if (iout_avg > 80)
            i_ma = (int)((uint32_t)iout_avg * I_MA_PER_RAW / 1000);
        else
            i_ma = 0;
        out_pct = (int)(((uint32_t)duty_now * 100u + PWM_MAX / 2u) / PWM_MAX);
        snap_ima = i_ma; snap_out = out_pct; snap_t0 = now;
    } else { i_ma = snap_ima; out_pct = snap_out; }
    if (update_v) {
        v10 = (int)((uint32_t)vin_raw * 693 / 4096);
        snap_v10 = v10; snap_v_t0 = now;
    } else v10 = snap_v10;
    if (v10 > 999) v10 = 999;
    rs_disp = tip_r_dmR;

    int no_tip = (dev_state == DS_NO_TIP);
    int asleep = (dev_state >= DS_SLEEP);
    if (no_tip) cur = 0;
    if (asleep || no_tip) disp_roll_active = 0;
    int curi = (int)cur;
    if (!no_tip && !asleep) curi = temp_roll_update((int)cur, now);
    uint16_t tcol = temp_state_color(curi);

    int i_c = i_ma;                 /* INA199 已按 PWM 平均，不能再乘 duty */
    if (i_c > 999999) i_c = 999999;
    if (i_c < 0) i_c = 0;
    int p_cw = v10 * i_c / 100;     /* P = V × 平均电流 */
    if (no_tip || asleep) { i_c = 0; p_cw = 0; out_pct = 0; }
    int bar_pct = (limit_pct > 0) ? out_pct * 100 / limit_pct : 0;
    if (bar_pct > 100) bar_pct = 100;
    if (no_tip || asleep) bar_pct = 0;

    mini_snprintf(stb, sizeof stb, "%dC", target_c);
    mini_snprintf(lmb, sizeof lmb, "%03d%%", limit_pct);
    if (no_tip) mini_snprintf(rsb, sizeof rsb, "%s", "OPEN");
    else if (rs_disp == 0xFFFF) mini_snprintf(rsb, sizeof rsb, "%s", "????");
    else mini_snprintf(rsb, sizeof rsb, "%d.%dR", rs_disp / 10, rs_disp % 10);
    mini_snprintf(vb, sizeof vb, "%d.%dV", v10 / 10, v10 % 10);
    if (i_c < 10000) mini_snprintf(ib, sizeof ib, "%d.%02dA", i_c / 1000, (i_c % 1000) / 10);
    else { int i10 = (i_c + 50) / 100; if (i10 < 1000) mini_snprintf(ib, sizeof ib, "%d.%dA", i10 / 10, i10 % 10); else { int ia = (i_c + 500) / 1000; if (ia > 999) ia = 999; mini_snprintf(ib, sizeof ib, "%dA", ia); } }
    if (p_cw < 1000) mini_snprintf(pb, sizeof pb, "%d.%02dW", p_cw / 100, p_cw % 100);
    else { int p10 = (p_cw + 5) / 10; if (p10 < 1000) mini_snprintf(pb, sizeof pb, "%d.%dW", p10 / 10, p10 % 10); else { int pw = (p_cw + 50) / 100; if (pw > 999) pw = 999; mini_snprintf(pb, sizeof pb, "%dW", pw); } }

    lcd_clear(C_BG);
    /* Apex frame, but v281 data coordinates stay untouched */
    lcd_fill(0, 0, 160, 1, C_TRACK);
    lcd_fill(0, 4, 2, 26, asleep ? C_COOL_DIM : C_OK);
    draw_line(152, 0, 159, 7, asleep ? C_COOL_DIM : C_RED2);
    draw_line(152, 32, 159, 39, asleep ? C_COOL_DIM : C_RED2);

    uint16_t lc = asleep ? C_DIM2 : C_DIM;
    uint16_t stc = readable565((asleep || no_tip) ? C_DIM2 : C_ST, C_OK);
    uint16_t lmc = readable565((asleep || no_tip) ? C_DIM2 : C_LM, C_COOL);
    uint16_t rsc = readable565(no_tip ? C_BAD : (asleep ? C_DIM2 : C_RS), C_BONE);
    uint16_t vc  = readable565((asleep || no_tip) ? C_DIM2 : C_V, C_BONE);
    uint16_t ic  = readable565((asleep || no_tip) ? C_DIM2 : C_I, C_BONE);
    uint16_t pc2 = readable565((asleep || no_tip) ? C_DIM2 : C_P, C_BONE);

    lcd_text(2, 2, "ST", lc);  lcd_text(20, 2, stb, stc);
    lcd_text(2, 13, "LM", lc); lcd_text(20, 13, lmb, lmc);
    lcd_text(2, 24, "RS", lc); lcd_text(20, 24, rsb, rsc);
    lcd_text(110, 2, "V", lc);  lcd_text(122, 2, vb, vc);
    lcd_text(110, 13, "I", lc); lcd_text(122, 13, ib, ic);
    lcd_text(110, 24, "P", lc); lcd_text(122, 24, pb, pc2);

    if (asleep) {
        const uint32_t ph = now % 2800u;
        uint16_t c1 = ph < 1400u ? C_COOL : C_COOL_DIM;
        draw_diamond(76, 12, 7, C_COOL);
        lcd_fill(75, 11, 2, 2, C_COOL);
        lcd_fill(59, 20, 36, 1, c1);
        lcd_text(62, 22, "SLEEP", C_DIM);
    } else if (no_tip) {
        const uint32_t ph = now % 1200u;
        uint16_t ec = ph < 600u ? C_OK : C_RED2;
        lcd_fill(48, 6, 1, 22, ec);
        lcd_fill(104, 6, 1, 22, ec);
        draw_diamond(76, 13, 8, C_BAD);
        lcd_text_big(71, 6, "!", C_BONE, 2);
        lcd_text(59, 22, "NO TIP", C_BAD);
    } else {
        uint16_t dc;
        if (tip_paused) dc = ((now / 600u) & 1u) ? C_PAUSE : 0x8A6A1F;
        else if (heat_on) dc = ((now / 600u) & 1u) ? C_OK : C_EMBER_DIM;
        else dc = ((now / 600u) & 1u) ? C_BLUE : 0x0008;
        lcd_fill(96, 4, 9, 1, C_TRACK);
        lcd_fill(104, 4, 1, 9, C_TRACK);
        lcd_fill(100, 6, 3, 3, dc);
        draw_temp_roll(50, 4, 13, 26, 2, tcol);
        draw_degree(96, 16, tcol);
    }

    if (fly_enable) {
        if (!heat_on && fly_last_id_ok) {
            /* ★ v023: 保存完成后底栏居中显示 12 位数据码，常驻到关闭/清空 */
            draw_bb_id(fly_last_crc64);
        } else {
            /* v019: 底栏录制进度；61S/123S 到 FULL 自动停热，FULL 停留 1s */
            uint16_t fly_n = FLY_LEN();
            uint16_t n = fly_i;
            if (n > fly_n) n = fly_n;
            int rp = (int)((uint32_t)n * 100u / fly_n);
            int full = (n >= fly_n) || (fly_full_t0 && now - fly_full_t0 < 167u);
            if (full) rp = 100;
            draw_meter(2, 34, 124, 5, rp, 0x04FF, C_TRACK);
            if (full) {
                mini_snprintf(pc, sizeof pc, "FULL");
                text_right(151, 33, pc, 0x04FF);
            } else {
                mini_snprintf(pc, sizeof pc, "%ds", (int)((uint32_t)n * 6u / 100u));
                text_right(151, 33, pc, C_BONE);
            }
        }
    } else {
        draw_meter(2, 34, 124, 5, bar_pct, C_OK, C_TRACK);
        mini_snprintf(pc, sizeof pc, "%d%%", bar_pct);
        text_right(151, 33, pc, (asleep || no_tip) ? C_DIM2 : C_BONE);
    }
    dbg_idle = (uint16_t)((uint32_t)(millis() - last_activity_ms) * MS_PER_TICK / 1000u);
    (void)st;
}

static void pdo_fill_cell(int i)
{
    fill_chamfer(pdo_cell_x(i), pdo_cell_y(i), 76, 8, 2, C_SEL);
}
static void pdo_label_cell(int i, int selL, int selT, int selR, int selB)
{
    char c[10];
    int x = pdo_cell_x(i), y = pdo_cell_y(i);
    int ok = (pdo_ok_mask & (1 << i)) != 0;
    int cov = (selL == x && selT == y && selR - selL == 76 && selB - selT == 8);
    uint16_t fg = cov ? C_BG : (ok ? C_GREEN : C_BAD);
    lcd_text(x + 4, y + 1, pdo_v[i], fg);
    if (ok) {
        int ma = husb238_pdo_ma(i);
        mini_snprintf(c, sizeof c, "%d.%02dA", ma / 1000, (ma % 1000) / 10);
        text_right(x + 72, y + 1, c, fg);
    } else {
        text_right(x + 72, y + 1, "--", fg);
    }
    if (i == pdo_gear) lcd_fill(x + 4, y + 7, 66, 1, cov ? C_BG : C_OK);
}
/* v329: 按指定前景色画档位文字，配合 clip 实现“红格从左点亮” */
static void pdo_label_cell_fg(int i, uint16_t fg)
{
    char c[10];
    int x = pdo_cell_x(i), y = pdo_cell_y(i);
    lcd_text(x + 4, y + 1, pdo_v[i], fg);
    if (pdo_ok_mask & (1 << i)) {
        int ma = husb238_pdo_ma(i);
        mini_snprintf(c, sizeof c, "%d.%02dA", ma / 1000, (ma % 1000) / 10);
        text_right(x + 72, y + 1, c, fg);
    } else {
        text_right(x + 72, y + 1, "--", fg);
    }
    if (i == pdo_gear) lcd_fill(x + 4, y + 7, 66, 1, fg);
}
static void pdo_hl_draw(int w)
{
    int i = pdo_sel;
    int x = pdo_cell_x(i), y = pdo_cell_y(i);
    int ok = (pdo_ok_mask & (1 << i)) != 0;
    uint16_t nf = ok ? C_GREEN : C_BAD;
    if (w < 0) w = 0;
    if (w > 76) w = 76;

    lcd_set_clip(x - 1, y - 1, x + 76, y + 8);
    fill_chamfer(x, y, 76, 8, 2, C_SEL);
    if (w >= 76) fill_chamfer(x, y, 76, 8, 2, C_OK);
    else if (w > 0) lcd_fill(x, y, w, 8, C_OK);

    lcd_set_clip(x, y, x + w - 1, y + 7);
    pdo_label_cell_fg(i, C_BG);
    lcd_set_clip(x + w, y, x + 75, y + 7);
    pdo_label_cell_fg(i, nf);
    lcd_set_clip(0, 0, 159, 39);
}
static void pdo_draw_bottom(void)
{
    lcd_fill(2, 37, 156, 2, C_TRACK);
    if (btn_centre() && g_btn_hold) {
        int p = (int)((uint32_t)g_btn_hold * 100u / LONG_PRESS_APPLY);
        if (p > 100) p = 100;
        lcd_fill(2, 37, 156 * p / 100, 2, C_OK);
    }
    lcd_fill(0, 39, 160, 1, C_TRACK);
}
static void pdo_draw_top(uint32_t now)
{
    int applying = btn_centre() && g_btn_hold && (pdo_ok_mask & (1 << pdo_sel));
    const char *right;
    uint16_t rc = C_DIM;
    if (pdo_apply_ok) { right = "OK"; rc = C_OK; }
    else if (applying) { right = "APPLY"; rc = C_OK; }
    else if (!husb_ack) { right = "NO PD"; rc = C_BAD; }
    else if (pdo_ok_mask == 0) { right = "NO PDO"; rc = C_BAD; }
    else if (last_apply && now - last_apply < APPLY_COOLDOWN) {
        right = ((now / 150u) & 1u) ? "SYNC" : "L+C:LIM";
    } else right = "L+C:LIM";
    lcd_fill(0, 8, 160, 1, C_TRACK);
    lcd_text(3, 1, "HOLD:APPLY", C_DIM);
    text_right(157, 1, right, rc);
}
static void draw_pdo(void)
{
    uint32_t now = millis();
    if (pdo_hl_t0) {
        uint32_t hel = now - pdo_hl_t0;
        int w;
        if (hel >= PDO_HL_TICKS) { w = 76; pdo_hl_done = 1; }
        else {
            w = (int)(76u * (uint32_t)ease_out_pm(hel, PDO_HL_TICKS) / 1000u);
            if (w < 1) w = 1;
        }
        pdo_hl_draw(w);
        return;
    }
    uint32_t pel = anim_el(pdo_anim_t0, now);
    int anim = (pdo_anim_t0 && pel < UI_STRETCH_MS);
    int diag = (pdo_x_from != pdo_x_to && pdo_y_from != pdo_y_to);
    int selL, selT, selR, selB;
    if (anim) {
        if (diag) {
            /* 直接斜向滑动：不再做 2D 大块拉伸，避免 12MHz SPI 超时 */
            uint32_t move_ms = UI_STRETCH_MS - 12u;
            int p = ease_out_pm(pel < move_ms ? pel : move_ms, move_ms);
            int px = pdo_x_from + (pdo_x_to - pdo_x_from) * p / 1000;
            int py = pdo_y_from + (pdo_y_to - pdo_y_from) * p / 1000;
            selL = px; selT = py; selR = px + 76; selB = py + 8;
        } else {
            int lead = stretch_lead(pel), trail = stretch_trail(pel);
            int ox = pdo_x_from, oy = pdo_y_from, nx = pdo_x_to, ny = pdo_y_to;
            if (nx >= ox) {
                selL  = ox + (nx - ox) * trail / 1000;
                selR = ox + (nx - ox) * lead / 1000 + 76;
            } else {
                selR = ox + 76 + (nx - ox) * trail / 1000;
                selL  = ox + (nx - ox) * lead / 1000;
            }
            if (ny >= oy) {
                selT = oy + (ny - oy) * trail / 1000;
                selB = oy + (ny - oy) * lead / 1000 + 8;
            } else {
                selB = oy + 8 + (ny - oy) * trail / 1000;
                selT = oy + (ny - oy) * lead / 1000;
            }
        }
    } else {
        selL = pdo_cell_x(pdo_sel);
        selT = pdo_cell_y(pdo_sel);
        selR = selL + 76;
        selB = selT + 8;
    }

    if (anim) {
        pdo_draw_top(now);
        pdo_flush_x0 = selL - 1; pdo_flush_y0 = selT - 1;
        pdo_flush_x1 = selR;     pdo_flush_y1 = selB;
        pdo_flush2_x0 = pdo_last_px - 1; pdo_flush2_y0 = pdo_last_py - 1;
        pdo_flush2_x1 = pdo_last_px + 77; pdo_flush2_y1 = pdo_last_py + 9;
        if (pdo_flush_x0 < 0) pdo_flush_x0 = 0;
        if (pdo_flush_y0 < 0) pdo_flush_y0 = 0;
        if (pdo_flush_x1 > 159) pdo_flush_x1 = 159;
        if (pdo_flush_y1 > 39) pdo_flush_y1 = 39;
        if (pdo_flush2_x0 < 0) pdo_flush2_x0 = 0;
        if (pdo_flush2_y0 < 0) pdo_flush2_y0 = 0;
        if (pdo_flush2_x1 > 159) pdo_flush2_x1 = 159;
        if (pdo_flush2_y1 > 39) pdo_flush2_y1 = 39;
        pdo_flush_valid = 1;
        int ux0, uy0, ux1, uy1;
        if (diag) {
            ux0 = ((pdo_last_px < selL) ? pdo_last_px : selL) - 1;
            ux1 = ((pdo_last_px > selL) ? pdo_last_px : selL) + 77;
            uy0 = ((pdo_last_py < selT) ? pdo_last_py : selT) - 1;
            uy1 = ((pdo_last_py > selT) ? pdo_last_py : selT) + 9;
            if (pdo_diag_first) {
                if (pdo_last_dirty_x0 < ux0) ux0 = pdo_last_dirty_x0;
                if (pdo_last_dirty_y0 < uy0) uy0 = pdo_last_dirty_y0;
                if (pdo_last_dirty_x1 > ux1) ux1 = pdo_last_dirty_x1;
                if (pdo_last_dirty_y1 > uy1) uy1 = pdo_last_dirty_y1;
                pdo_diag_first = 0;
            }
        } else {
            int ox = pdo_x_from, oy = pdo_y_from, nx = pdo_x_to, ny = pdo_y_to;
            ux0 = ((ox < nx) ? ox : nx) - 1;
            ux1 = ((ox > nx) ? ox : nx) + 77;
            uy0 = (oy < ny) ? oy : ny;
            uy1 = ((oy > ny) ? oy : ny) + 8;
        }
        if (ux0 < 0) ux0 = 0;
        if (ux1 > 159) ux1 = 159;
        if (uy0 < 9) uy0 = 9;
        if (uy1 > 35) uy1 = 35;
        pdo_dirty_x0 = ux0; pdo_dirty_y0 = uy0;
        pdo_dirty_x1 = ux1; pdo_dirty_y1 = uy1;

        lcd_set_clip(ux0, uy0, ux1, uy1);
        lcd_fill(ux0, uy0, ux1 - ux0 + 1, uy1 - uy0 + 1, C_BG);
        for (int i = 0; i < 6; i++) {
            int x = pdo_cell_x(i), y = pdo_cell_y(i);
            if (x <= ux1 && x + 75 >= ux0 && y <= uy1 && y + 7 >= uy0) pdo_fill_cell(i);
        }
        fill_chamfer(selL, selT, selR - selL, selB - selT, 2, C_OK);
        for (int i = 0; i < 6; i++) {
            int x = pdo_cell_x(i), y = pdo_cell_y(i);
            if (x <= ux1 && x + 75 >= ux0 && y <= uy1 && y + 7 >= uy0) pdo_label_cell(i, selL, selT, selR, selB);
        }
        lcd_set_clip(0, 0, 159, 39);
        pdo_draw_bottom();
        if (diag) { pdo_last_px = selL; pdo_last_py = selT; }
        pdo_last_dirty_x0 = ux0; pdo_last_dirty_y0 = uy0;
        pdo_last_dirty_x1 = ux1; pdo_last_dirty_y1 = uy1;
        return;
    }

    lcd_clear(C_BG);
    pdo_flush_valid = 0;
    pdo_draw_top(now);

    for (int i = 0; i < 6; i++) pdo_fill_cell(i);
    if (!pdo_hl_hold) {
        fill_chamfer(selL, selT, selR - selL, selB - selT, 2, C_OK);
    }
    if (pdo_hl_hold) {
        for (int i = 0; i < 6; i++) pdo_label_cell(i, -1000, -1000, -1000, -1000);
        if (pdo_gear == pdo_sel) {
            int sx = pdo_cell_x(pdo_sel), sy = pdo_cell_y(pdo_sel);
            lcd_fill(sx + 4, sy + 7, 66, 1, C_SEL);   /* 入场期间不露红色下划线 */
        }
    } else {
        for (int i = 0; i < 6; i++) pdo_label_cell(i, selL, selT, selR, selB);
    }
    pdo_draw_bottom();

    pdo_last_px = selL; pdo_last_py = selT;
    pdo_last_dirty_x0 = selL; pdo_last_dirty_y0 = selT;
    pdo_last_dirty_x1 = selR - 1; pdo_last_dirty_y1 = selB - 1;
}

static void draw_limit(void)
{
    char b[24];
    lcd_clear(C_BG);
    int v10 = (int)((uint32_t)vin_raw * 693u / 4096u);
    int i_ma = (int)((uint32_t)iout_avg * I_MA_PER_RAW / 1000);
    if (v10 > 999) v10 = 999;
    if (i_ma > 9999) i_ma = 9999;
    mini_snprintf(b, sizeof b, "%d%%", limit_pct);
    lcd_text_big(4, 1, b, C_OK, 2);
    lcd_text(4, 24, "POWER LIMIT", C_DIM);

    mini_snprintf(b, sizeof b, "%d.%dV", v10 / 10, v10 % 10);
    lcd_text(112, 3, "V", C_DIM); text_right(150, 3, b, C_BONE);
    mini_snprintf(b, sizeof b, "%d.%02dA", i_ma / 1000, (i_ma % 1000) / 10);
    lcd_text(112, 12, "I", C_DIM); text_right(150, 12, b, C_BONE);
    lcd_text(112, 21, "R", C_DIM);
    if (dev_state == DS_NO_TIP) text_right(150, 21, "OPEN", C_DIM);
    else if (tip_r_dmR == 0xFFFF) text_right(150, 21, "????", C_DIM);
    else { mini_snprintf(b, sizeof b, "%d.%dR", tip_r_dmR / 10, tip_r_dmR % 10); text_right(150, 21, b, C_BONE); }

    lcd_fill(156, 0, 3, 32, C_TRACK);
    int fh = 32 * limit_pct / 100;
    if (fh) { lcd_fill(156, 32 - fh, 3, fh, C_OK); lcd_fill(154, 32 - fh, 7, 2, C_OK); }
    for (int k = 1; k < 4; k++) lcd_fill(154, 32 * k / 4, 7, 1, C_TRACK);
    lcd_text(2, 33, "L/R ADJ", C_DIM2);
}

/* ★ v216: SET 页 —— 图标 + 4 字中文标签 + 右对齐数值 + 滚动条 */
static void draw_cn16(int x, int y, int idx, uint16_t c);
static void draw_cn16_right(int rx, int y, int idx, uint16_t c);
static void draw_cn16_pair_right(int rx, int y, int a, int b, uint16_t c);
static void draw_cn16_triple_right(int rx, int y, int a, int b, int d, uint16_t c);
static void draw_cn9(int x, int y, int idx, uint16_t c);
static const uint8_t SET_ICON_ROW[SET_N] = { 0, 1, 2, 3, 4, 3, 5, 6, 7, 8, 6, 9 };

static void set_label(int i, int x, int y, uint16_t c)
{
    int a, b, e, d;
    switch (i) {
    case 0:  a=35; b=36; e=0;  d=1;  break;   /* 屏幕亮度 */
    case 1:  a=35; b=36; e=2;  d=3;  break;   /* 屏幕方向 */
    case 2:  a=9;  b=10; e=2;  d=37; break;   /* 休眠方式 */
    case 3:  a=16; b=17; e=38; d=39; break;   /* 静置时间 */
    case 4:  a=18; b=19; e=38; d=39; break;   /* 暂停时间 */
    case 5:  a=9;  b=10; e=38; d=39; break;   /* 休眠时间 */
    case 6:  a=40; b=41; e=21; d=22; break;   /* 操作逻辑 */
    case 7:  a=11; b=5;  e=27; d=28; break;   /* 运动阈值 */
    case 8:  a=42; b=43; e=5;  d=34; break;   /* 开机动画 */
    case 9:  a=42; b=43; e=30; d=31; break;   /* 开机加热 */
    case 10:                                  /* 黑匣子（v019 缩为 3 字，给 123S 让位） */
        draw_cn16(x, y, 86, c);
        draw_cn16(x + 16, y, 87, c);
        draw_cn16(x + 32, y, 88, c);
        return;
    default: a=32; b=33; e=44; d=1;  break;   /* 常用温度 */
    }
    draw_cn16(x, y, a, c);
    draw_cn16(x + 16, y, b, c);
    draw_cn16(x + 32, y, e, c);
    draw_cn16(x + 48, y, d, c);
}

static void draw_time_unit(int x, int y, int is_min, uint16_t c)
{
    /* 5×5 小号 S/M，数字后留空，避免与数字 5 混淆 */
    static const uint8_t US[5] = {0x0E, 0x10, 0x0E, 0x01, 0x1F};
    static const uint8_t UM[5] = {0x11, 0x1B, 0x15, 0x11, 0x11};
    const uint8_t *g = is_min ? UM : US;
    for (int r = 0; r < 5; r++)
        for (int col = 0; col < 5; col++)
            if (g[r] & (0x10 >> col)) lcd_px(x + col, y + r, c);
}

static void set_value(int i, int y, int sel, int edit, uint16_t fg)
{
    char b[16];
    int vy = y + 3;
    switch (i) {
    case 0:
        mini_snprintf(b, sizeof b, "%d%%", cfg_bright);
        text_big_right(146, vy, b, fg, 2);
        {
            uint16_t trk = (sel && edit) ? 0x0200 : C_TRACK;
            uint16_t fil = (sel && edit) ? C_BG : C_OK;
            lcd_fill(100, y + 18, 46, 1, trk);
            lcd_fill(100, y + 18, 46 * cfg_bright / 100, 1, fil);
        }
        break;
    case 1:
        if (cfg_rot_mode == 0)      { draw_cn16_pair_right(146, y + 2, 4, 5, fg); }
        else if (cfg_rot_mode == 1) { draw_cn16_pair_right(146, y + 2, 6, 7, fg); }
        else                        { draw_cn16_pair_right(146, y + 2, 8, 7, fg); }
        break;
    case 2:
        if (sleep_mode == 1)      { draw_cn16_pair_right(146, y + 2, 11, 5, fg); }
        else if (sleep_mode == 2) { draw_cn16_pair_right(146, y + 2, 12, 13, fg); }
        else                      { draw_cn16_pair_right(146, y + 2, 14, 15, fg); }
        break;
    case 3:
        mini_snprintf(b, sizeof b, "%d", cfg_idle_s);
        text_big_right(136, vy, b, fg, 2);
        draw_time_unit(141, y + 7, 0, fg);
        break;
    case 4:
        mini_snprintf(b, sizeof b, "%d", cfg_pause_s);
        text_big_right(136, vy, b, fg, 2);
        draw_time_unit(141, y + 7, 0, fg);
        break;
    case 5:
        mini_snprintf(b, sizeof b, "%d", cfg_sleep_min);
        text_big_right(136, vy, b, fg, 2);
        draw_time_unit(141, y + 7, 1, fg);
        break;
    case 6:
        if (cfg_logi == 0) { draw_cn16_pair_right(146, y + 2, 23, 24, fg); }
        else               { draw_cn16_pair_right(146, y + 2, 25, 26, fg); }
        break;
    case 7:
        mini_snprintf(b, sizeof b, "%d", cfg_motion_th);
        text_big_right(146, vy, b, fg, 2);
        break;
    case 8:
        draw_cn16_right(146, y + 2, cfg_boot_anim ? 29 : 14, fg);
        break;
    case 9:
        draw_cn16_right(146, y + 2, cfg_boot_heat ? 29 : 14, fg);
        break;
    case 11:
        for (int k = 0; k < 3; k++) {
            int sx = 96 + k * 19;
            char v[8];
            mini_snprintf(v, sizeof v, "%d", cfg_preset[k]);
            if (sel && edit && k == preset_edit_i) {
                lcd_fill(sx - 2, y + 4, 20, 13, C_BG);
                lcd_text(sx, y + 6, v, C_OK);
            } else {
                lcd_text(sx, y + 6, v, fg);
                if (k == preset_idx) lcd_fill(sx, y + 18, 17, 1, fg);
            }
        }
        lcd_text(152, y + 6, "C", fg);
        break;
    case 10: {
        uint8_t v = (edit && sel) ? fly_sel : (uint8_t)(fly_enable ? (fly_dur ? 2 : 1) : 0);
        if (v == 3) {
            draw_cn16_pair_right(146, y + 2, 92, 93, fg);   /* 清空 */
        } else if (v == 0) {
            draw_cn16_right(146, y + 2, 14, fg);            /* 关 */
        } else {
            char b[8];
            mini_snprintf(b, sizeof b, "%d", v == 2 ? 123 : 61);
            text_big_right(136, y + 3, b, fg, 2);
            draw_time_unit(141, y + 7, 0, fg);
        }
        break;
    }
    default: break;
    }
}
static void draw_hold_progress(void)
{
    if (btn_centre() && g_btn_hold > 0) {
        int w = (int)((uint32_t)g_btn_hold * 158u / LONG_PRESS_MS);
        if (w > 158) w = 158;
        lcd_fill(0, 38, w, 1, C_OK);
    }
}

static int set_edit_ax(int i)
{
    char b[8];
    int start;
    switch (i) {
    case 0:
        mini_snprintf(b, sizeof b, "%d%%", cfg_bright);
        start = 146 - text_w(b) * 2;
        return start - 8 < 92 ? 92 : start - 8;
    case 1: case 2: case 6:
        return 106;
    case 3: case 4:
        mini_snprintf(b, sizeof b, "%d", cfg_idle_s);
        start = 136 - text_w(b) * 2;
        return start - 8;
    case 5:
        mini_snprintf(b, sizeof b, "%d", cfg_sleep_min);
        start = 136 - text_w(b) * 2;
        return start - 8;
    case 7:
        mini_snprintf(b, sizeof b, "%d", cfg_motion_th);
        start = 146 - text_w(b) * 2;
        return start - 8;
    case 8: case 9:
        return 122;
    case 10:
        return 84;   /* v019: 给 123S 留出值区 */
    default:
        return 84;
    }
}
static void draw_set(void)
{
    char b[24];
    uint32_t now = millis();
    lcd_clear(C_BG);
    int base = set_view_of(set_sel);
    if (base < 0) base = 0;
    int pill_y = (set_sel - base) * 20;
    uint8_t clear_done = (set_sel == 10 && fly_clear_t0 && now - fly_clear_t0 < 250u);

    lcd_set_clip(0, 0, 156, 40);
    if (!set_edit) {
        lcd_fill(0, pill_y, 157, 20, C_SEL);
        lcd_fill(0, pill_y, 2, 20, C_OK);
    }
    for (int r = 0; r < 2; r++) {
        int i = base + r;
        if (i >= SET_N) break;
        int y = r * 20;
        int sel = (i == set_sel);
        int edit = sel && set_edit;
        int cov = (pill_y == y && !set_edit);
        uint16_t fg;
        if (edit) { lcd_fill(0, y, 157, 20, C_OK); fg = C_BG; }
        else fg = cov ? C_BONE : C_DIM;

        mini_snprintf(b, sizeof b, "%02d", i < 6 ? i + 1 : i);
        lcd_text_big(4, y + 3, b, edit ? C_BG : (cov ? C_OK : C_DIM2), 2);
        set_label(i, 30, y + 2, fg);

        int clear_hold = (i == 10 && sel && set_edit && fly_sel == 3 &&
                          btn_centre() && g_btn_hold > 0 && !clear_done);
        int show_done = (i == 10 && clear_done);
        int show_hint = (i == 10 && sel && set_edit && fly_sel == 3 && !clear_done);
        if (show_done) {
            /* v017: 编辑行是 C_OK 底色，成功提示不能用 C_OK，否则看不见 */
            uint16_t dc = set_edit ? C_BG : (fly_clear_ok ? C_OK : C_BAD);
            if (fly_clear_ok) { draw_cn16(120, y + 2, 94, dc); draw_cn16(136, y + 2, 92, dc); }  /* 已清 */
            else              { draw_cn16(120, y + 2, 95, dc); draw_cn16(136, y + 2, 96, dc); }  /* 失败 */
        } else if (show_hint) {
            /* v017: 只显示大字“清空”；长按清空的操作说明写进 master 说明书 */
            draw_cn16(120, y + 2, 92, fg);   /* 清 */
            draw_cn16(136, y + 2, 93, fg);   /* 空 */
            if (clear_hold) {
                int p = (int)((uint32_t)g_btn_hold * 100u / LONG_PRESS_MS);
                if (p > 100) p = 100;
                lcd_fill(96, y + 18, 60, 2, C_TRACK);
                lcd_fill(96, y + 18, 60 * p / 100, 2, C_BONE);
            }
        } else {
            set_value(i, y, sel, set_edit, fg);
        }

        if (sel && !clear_hold && !show_hint && !show_done) {
            if (set_edit && i != 11) {
                int ax = set_edit_ax(i);
                lcd_text(ax, y + 6, "<", C_BG);
                lcd_text(150, y + 6, ">", C_BG);
                if ((set_flash_t0 && now - set_flash_t0 < 33u) || ((now / 300u) & 1u) == 0u)
                    lcd_fill(ax + 7, y + 18, 140 - (ax + 7), 1, C_BG);
            }
        }
    }
    lcd_set_clip(0, 0, 159, 39);
    lcd_fill(157, 0, 2, 40, C_TRACK);
    lcd_fill(157, (40 - 7) * set_sel / (SET_N - 1), 2, 7, C_OK);
    draw_hold_progress();
}
