static void draw_cn9(int x, int y, int idx, uint16_t c)
{
    for (int r = 0; r < 9; r++) {
        uint16_t bits = CN9[idx][r];
        for (int col = 0; col < 9; col++)
            if (bits & (0x100u >> col)) lcd_px(x + col, y + r, c);
    }
}

