            break;
        case 1:
            draw_cn16(20, y + 2, CN_JI, fg); draw_cn16(36, y + 2, 46, fg);
            lcd_text_big(56, y + 3, "I", fg, 2);
            break;
        case 2:
            draw_cn16(20, y + 2, CN_WEI, fg); draw_cn16(36, y + 2, 46, fg);
            lcd_text_big(56, y + 3, "D", fg, 2);
            break;
        case 3:
            draw_cn16(20, y + 2, CN_MU, fg); draw_cn16(36, y + 2, CN_BIAO, fg);
