/* ★ v217: 统一呈现 —— 亮度 + 整屏刷新 / 整页滑动翻页 */
static uint32_t ui_frame_ms(uint32_t now)
{
    if (ui_slide) return UI_SLIDE_FRAME_TICKS;
    if (pdo_hl_t0) return UI_FAST_TICKS;
    if ((page == 0 || page == 13 || page == 14) && disp_roll_active) return 2u;   /* 主界面/CAL 温度滚动 */
    if (menu_anim_t0 && now - menu_anim_t0 < UI_STRETCH_MS + 12u) return UI_FAST_TICKS;
    if (pdo_anim_t0 && now - pdo_anim_t0 < UI_STRETCH_MS + 12u) return UI_FAST_TICKS;
    if (set_anim_t0 && now - set_anim_t0 < UI_STRETCH_MS + 12u) return UI_FAST_TICKS;
    if (pid_anim_t0 && now - pid_anim_t0 < UI_STRETCH_MS + 12u) return UI_FAST_TICKS;
    if ((page == 1 || page == 12 || page == 13 || page == 14 || page == 15 || page == 17) && btn_centre()) return UI_FAST_TICKS;
    if (page == 0 || page == 13) return 25u;      /* v242: 主界面/CAL 150ms */
    if (page == 14) return 25u;                   /* v248: PID 实时 PV/OUT 150ms */
    return 100u;                                  /* 其他页面 600ms */
}
static void ui_present(void)
{
    int pct = cfg_bright;
    /* ★ v258: 我们调的是画面亮度，不是背光 PWM；深度 5% 太黑，改成 15% */
    if (dev_state == DS_DEEP) pct = 15;
    else if (dev_state == DS_STANDBY) pct = 15;
    else if (dev_state == DS_SLEEP) pct = 50;
    else if (page == 12 && pct < 35) pct = 35;   /* 调亮度时保底可见 */
    lcd_dim_pct(pct);
    uint32_t now = millis();
    if (ui_slide) {
        if (ui_slide_boot) {
            uint32_t gap = now - ui_slide_last;
            ui_slide_last = now;
            if (gap <= UI_SLIDE_FRAME_TICKS + 2u) {
                if (ui_slide_stable < 3u) ui_slide_stable++;
            } else {
                ui_slide_stable = 0;
            }
            if (ui_slide_stable < 3u) {
                ui_anim_t0 = now;   /* 初始化还没收尾，先保持 READY 不推进 */
                return;
            }
            ui_slide_boot = 0;      /* 主循环已连续稳定出帧，正式开始斜切 */
            ui_anim_t0 = now;
        }
        uint32_t el = now - ui_anim_t0;
        int e = (el >= UI_SLIDE_TICKS) ? 1000 : ease_out_pm(el, UI_SLIDE_TICKS);
        /* 开机阶段主循环可能被 PD/传感器初始化卡住；限制单帧步进，
         * 避免 el 一次跨过整段动画，只显示两帧就跳到主界面。 */
        if (e > ui_slide_pm + UI_SLIDE_MAX_STEP) e = ui_slide_pm + UI_SLIDE_MAX_STEP;
        if (e > 1000) e = 1000;
        if (e > ui_slide_pm) lcd_wipe_strip(ui_slide == 2 ? -1 : 1, ui_slide_pm, e);
        ui_slide_pm = e;
        if (e >= 1000) {
            ui_slide = 0;
            ui_slide_ready = 0;
            ui_slide_pm = 0;
            ui_slide_boot = 0;
            ui_slide_stable = 0;
            if (page == 1 && pdo_hl_pending) {
                pdo_hl_pending = 0;
                pdo_hl_hold = 0;
                pdo_hl_done = 0;
                pdo_hl_t0 = millis();
                if (!pdo_hl_t0) pdo_hl_t0 = 1;
                ui_dirty = 1;
            }
            lcd_flush();
        }
        return;
    }

    int rx = 0, ry = 0, rw = 0, rh = 0, partial = 0;
    if (page == 1 && pdo_hl_t0) {
        int hx = pdo_cell_x(pdo_sel), hy = pdo_cell_y(pdo_sel);
        rx = hx - 1; ry = hy - 1; rw = 78; rh = 10; partial = 1;
    } else if (page == 1 && pdo_anim_t0 && now - pdo_anim_t0 < UI_STRETCH_MS) {
        if (pdo_flush_valid) {
            rx = pdo_flush_x0; ry = pdo_flush_y0;
            rw = pdo_flush_x1 - pdo_flush_x0 + 1;
            rh = pdo_flush_y1 - pdo_flush_y0 + 1;
        } else {
            rx = pdo_dirty_x0; ry = pdo_dirty_y0;
            rw = pdo_dirty_x1 - pdo_dirty_x0 + 1;
            rh = pdo_dirty_y1 - pdo_dirty_y0 + 1;
        }
        partial = 1;
    } else if (page == 10 && menu_anim_t0 && now - menu_anim_t0 < UI_STRETCH_MS + 12u) {
        rx = 0; ry = 9; rw = 160; rh = 30; partial = 1;
    } else if (page == 12 && set_anim_t0 && now - set_anim_t0 < UI_STRETCH_MS + 12u) {
        rx = 0; ry = 8; rw = 160; rh = 31; partial = 1;
    } else if (page == 14 && pid_anim_t0 && now - pid_anim_t0 < UI_STRETCH_MS + 12u) {
        rx = 0; ry = 8; rw = 160; rh = 31; partial = 1;
    }

    if (partial && lcd_get_orientation() < 4) {
        if (ui_header_flush) {
            lcd_flush_rect(0, 0, 160, 9);
            ui_header_flush = 0;
        }
        lcd_flush_rect(rx, ry, rw, rh);
        if (page == 1 && pdo_flush_valid) {
            int sx0 = pdo_flush2_x0, sy0 = pdo_flush2_y0;
            int sx1 = pdo_flush2_x1, sy1 = pdo_flush2_y1;
            if (!(sx0 == rx && sy0 == ry && sx1 == rx + rw - 1 && sy1 == ry + rh - 1))
                lcd_flush_rect(sx0, sy0, sx1 - sx0 + 1, sy1 - sy0 + 1);
        }
        if (page == 1 && btn_centre())
            lcd_flush_rect(2, 36, 156, 2);
    } else {
        lcd_flush();
        ui_header_flush = 0;
    }
    if (page == 1 && pdo_hl_t0 && pdo_hl_done) { pdo_hl_t0 = 0; pdo_hl_done = 0; }
}

static void draw_cn16(int x, int y, int idx, uint16_t c)
{
    const uint8_t *bm = CN16[idx];
    for (int r = 0; r < 16; r++) {
        for (int q = 0; q < 16; q++) {
            uint8_t a = *bm++;
            if (a) lcd_blend_px(x + q, y + r, c, a);
        }
    }
}

/* 中文值按墨迹右缘对齐：调用传 rx=146，最右墨迹落到 145 */
static void draw_cn16_right(int rx, int y, int idx, uint16_t c)
{
    draw_cn16(rx - 1 - CN16_RIGHT[idx], y, idx, c);
}
static void draw_cn16_pair_right(int rx, int y, int a, int b, uint16_t c)
{
    int xb = rx - 1 - CN16_RIGHT[b];
    draw_cn16(xb - 16, y, a, c);
    draw_cn16(xb, y, b, c);
}
static void draw_cn16_triple_right(int rx, int y, int a, int b, int d, uint16_t c)
{
    int xd = rx - 1 - CN16_RIGHT[d];
    draw_cn16(xd - 32, y, a, c);
    draw_cn16(xd - 16, y, b, c);
    draw_cn16(xd, y, d, c);
}

