static void pdo_mask_refresh(void)
{
    if (!husb_ack) { pdo_ok_mask = 0; return; }
    uint8_t m = 0;
    for (int i = 0; i < 6; i++) {
        uint8_t v = husb238_read((uint8_t)(0x02 + i));
        pdo_raw[i] = v;
        if (v & 0x80) m |= (uint8_t)(1 << i);
    }
    pdo_ok_mask = m;
}

/* ★ v86: 测量窗口诊断 — 按 PWM 相位分桶统计 ADC 原始值
 * 用法: 调试器读 dbg_pmn/dbg_pmx/dbg_psum/dbg_pn → 画出"噪声 vs 相位"曲线
 * 加热导通相 = 相位 < 当前 duty 的桶 (PWM1 模式) */
#define WIN_PH 32
volatile uint16_t dbg_pmn[WIN_PH], dbg_pmx[WIN_PH];
volatile uint32_t dbg_psum[WIN_PH], dbg_pn[WIN_PH];
/* ★ v90: 设备状态机（对齐设计基线 0x10000034 状态字节思路） */
#define DS_NO_TIP  0   /* 未插入: ADC 开路饱和 */
#define DS_READY   1   /* 已插入·正常（设计基线状态码 1 同义）*/
#define DS_SLEEP   2   /* 休眠: 显示灭 + 加热锁定 */
#define TIP_RAW_THRESHOLD 4000   /* PD245 设计基线 NoIron 阈值；无头实测 raw≈4091 */
#define PROT_RAW_HI  4000
#define PROT_RAW_LO  3100
#define DEBOUNCE_N   5   /* >= 此值 = TC 开路(未插入)；设计基线表上限 3500 */
#define SLEEP_AFTER_S     30     /* ★ v105: 30s 验证模式(手册 0-250s 可调, 设置页后改回) */
volatile uint8_t dev_state = DS_NO_TIP;
/* ★ v110: 设计基线休眠机制移植（文档已抽验一致）
 * 检测: SC7A20 10Hz, 运动量=Σ|Δaxis|≥25=运动拍; 醒态静止>125拍(12.5s)→睡; 睡态连续3运动拍→醒
 * 递进: 休眠30s→待机(亮度15%) → 5min→深度(隐藏) → 按键恢复 */
#define STANDBY_AFTER_S   30        /* 休眠 30 秒 → 待机档 */
#define DEEP_AFTER_S      300       /* 待机 300 秒 → 深度档 */
#define MOTION_TH         25        /* 设计基线默认运动阈值 */
#define WAKE_RUN          3         /* 连续 3 运动拍唤醒 */
#define IDLE_SAMPLES      125       /* 10Hz × 12.5s */
static uint8_t asleep = 0;          /* SC7A20 判定: 0=醒 1=睡 */
static uint16_t idle_cnt = 0;       /* 静止拍计数 */
static uint8_t motion_run = 0;      /* 连续运动拍 */
#define DS_STANDBY  3
#define DS_DEEP     4

/* ★ v268: 唤醒时按睡前的插头状态恢复，未插头直接进未插入界面，避免闪一帧室温 */
static uint8_t wake_dev_state(void)
{
    return (tip_was_open || tip_gone_cnt >= 3) ? DS_NO_TIP : DS_READY;
}

/* ★ v92: 手册功能 — 休眠方式(运动/磁吸/关) + 暂停状态 + 状态灯闪烁 */
volatile uint16_t pause_ctr = 0;    /* 无运动秒计数 */
volatile uint8_t tip_paused = 0;    /* 1=暂停加热(运动休眠触发) */
#define PAUSE_AFTER_S   5           /* 手册: 静置一段时间→暂停(先 5s, 可调) */
#define MOTION_THRESH   6           /* 加速度变化阈值(8bit 量纲) */
volatile uint16_t sleep_ctr = 0; /* 秒计数 */
volatile uint8_t sleep_awake = 1;

volatile uint16_t dbg_win_duty = 0, dbg_win_last = 0, dbg_win_mode = 1;
volatile uint16_t dbg_win_fix = 0;   /* mode==2 时强制此 duty (0..319, 0=正常PID) */

static inline void win_diag_sample(uint16_t rv)
{
    uint16_t c = TIM2->CNT;                 /* 0..319 (ARR=319) */
    uint16_t ph = (uint16_t)((uint32_t)c * WIN_PH / 320u);
    if (ph >= WIN_PH) ph = WIN_PH - 1;
    if (dbg_pn[ph] == 0 || rv < dbg_pmn[ph]) dbg_pmn[ph] = rv;
    if (rv > dbg_pmx[ph]) dbg_pmx[ph] = rv;
    dbg_psum[ph] += rv;
    dbg_pn[ph]++;
    dbg_win_last = rv;
}

/* v237: 主循环高频轮询电流，只在加热 PWM 导通相采样（每 6ms 最多一次） */
static uint16_t iout_peak = 0;   /* v263: 200ms 窗口内的导通相峰值电流 */
static void poll_current(uint32_t now)
{
    (void)now;
    /* 25kHz PWM 的导通相只有几微秒，单次主循环采样经常错过；
     * 每次突发采 8 次，取导通样本平均/峰值。 */
    uint32_t sum = 0;
    int n = 0;
    uint16_t peak = 0;
    for (int k = 0; k < 8; k++) {
        uint16_t s = adc_iout();
        if (s > 80) {
            sum += s;
            n++;
            if (s > peak) peak = s;
        }
    }
    if (n) {
        if (peak > iout_peak) iout_peak = peak;
        if (i_n < 1000u) { i_sum += (uint16_t)(sum / (uint32_t)n); i_n++; }
    } else if (duty_now == 0) {
        iout_peak = 0;
        iout_raw = 0;
    }
}

static void current_window_tick(uint32_t now)
{
    /* ★ v263: 200ms 取一次导通相峰值；主界面 I/P 用 iout_raw，
     *   LIM 页继续用 iout_avg */
    if (now - i_win_t0 >= 33u) {
        /* 显示用峰值，保护/内阻用平均值 —— 两路分开 */
        if (iout_peak > 80) iout_disp_raw = iout_peak;
        else if (duty_now == 0) iout_disp_raw = 0;
        iout_peak = 0;
        if (i_n) iout_avg = (uint16_t)(i_sum / i_n);
        else if (duty_now == 0) iout_avg = 0;
        iout_raw = iout_avg;
        if (duty_now == 0) iout_raw = 0;
        i_sum = 0; i_n = 0; i_win_t0 = now;
    }
}

static uint8_t boot_orient_ok = 0;

/* ★ v259: 开机方向判定：优先 gx（水平转向），gx 不明确时用 gz 符号兜底；
 *   只有方向确定后才允许点亮开机画面 */
static int boot_orient_sample(int8_t x, int8_t y, int8_t z)
{
    (void)y;
    int r = -1;
    if (x > 25)       r = 1;
    else if (x < -25) r = 0;
    else if (z > 40)  r = 1;
    else if (z < -40) r = 0;
    if (r < 0) return 0;
    rot180 = (uint8_t)r;
    lcd_set_rot180(rot180);
    boot_orient_ok = 1;
    ui_dirty = 1;
    return 1;
}

int main(void)
{
    backlight_early_off();                    /* v228: 先灭背光，杜绝上电闪一下 */
    clock_init();
    gpio_init();                              /* 鑳屽厜寮曡剼鍦ㄦ鎷変綆 (棣栧抚鍓嶄笉浜? */
    spi2_init();
    adc_init();
    pwm_init();
    lcd_init();                               /* 清屏后保持黑场；开机动画前不再把主界面送进 GRAM */
    /* ★ v261: 不在启动动画前 flush 主界面，避免上电背光瞬亮时闪出主界面内容 */
    /* ★ v170: 背光延后 —— 等加速度计就绪(方向确定)后再点亮，
     *   避免开机瞬间显示反面；最多等 3.5s 兜底 */
    boot_bl_on = 0;
    /* 鎱㈡搷浣滃叏閮ㄦ斁鍦ㄥ睆骞曠偣浜箣鍚?(v8 椤哄簭鐤戜技鍚姩宕╂簝, 鍥為€€ v7 缁撴瀯) */
    husb_ack = 0;
    for (int t = 0; t < 5; t++) {   /* ★ v229: HUSB238 上电较慢，首次扫描没 ACK 就重试 */
        i2c_scan();
        husb_ack = (i2c_ack[1] & (1 << 0)) != 0;
        if (husb_ack) break;
        delay_ms(50);
    }
    accel_init();
    /* ★ v164: 上电按当前姿态决定屏幕方向 —— 重试直到传感器出数（最多 ~200ms）
     *   注：SC7A20 上电后首帧需要 ~10ms，且 i2c 首读可能 NAK → 必须重试，
     *       否则 rot180 会被固定成 0（用户实测：开机方向不对的根因） */
    {
        int8_t bx = 0, by = 0, bz = 0;
        /* ★ v166: 传感器与 PD 共用供电 —— 开机时 PD 可能尚未协商完成，
         *   扫描必然失败（调试器实测 accel_addr=0 一直不恢复）。
         *   这里先快速试 ~160ms；失败则交给主循环每 500ms 持续重试。 */
        for (int try_n = 0; try_n < 60; try_n++) {
            for (volatile int w0 = 0; w0 < 72000; w0++) { }   /* ★ v218: ~4ms @24MHz */
            accel_read_xyz(&bx, &by, &bz);
            if (bx || by || bz) {
                accel_ready = 1;
                if (boot_orient_sample(bx, by, bz)) break;
            }
            if ((try_n & 7) == 7) { i2c_scan(); accel_init(); }
        }
    }
    pdo_mask_refresh();                       /* 寮€鏈哄嵆璇诲厖鐢靛櫒 PDO 骞挎挱 */
    /* ★ v212: 开机加热 —— 插着发热芯上电自动开始加热（SET 可关） */
    if (cfg_boot_heat && dev_state == DS_READY && !heat_on) { heat_on = 1; ui_dirty = 1; }

    /* --- 璁剧疆鎸佷箙鍖? 涓婄數鍔犺浇, 棣栨涓洪粯璁ゅ€?--- */
    int cfg_migrated = 0;
    {
        settings_t ld;
        if (flash_settings_load(&ld)) {
            int col_ok = 0;
            target_c = ld.target_c;
    if (ld.reserved & 0x80000000u) {   /* ★ v136: 有效标记 */
        for (int ci = 0; ci < 6; ci++) {
            int v = (int)((ld.reserved >> (ci * 5)) & 0x1F) - 16;
            if (v >= -15 && v <= 15) cal_delta[ci] = (int8_t)v;
        }
    }
            limit_pct = ld.limit_pct;
            pdo_gear = ld.pdo_gear;
            pdo_sel = ld.pdo_gear;
            /* ★ v211: 加载扩展字段（全部 SET 菜单项 + 常用温度） */
            if (ld.ext_valid == 0x45585431u
                && ld.ext_chk == (ld.ext_valid ^ ld.misc_a ^ ld.misc_b ^ ld.preset01 ^ ld.preset2)) {
                cfg_bright    = (int)(ld.misc_a & 0xFFu);           if (cfg_bright < 5 || cfg_bright > 100) cfg_bright = 100;
                cfg_rot_mode  = (uint8_t)((ld.misc_a >> 8) & 3u);   if (cfg_rot_mode > 2) cfg_rot_mode = 0;
                sleep_mode    = (uint8_t)((ld.misc_a >> 10) & 3u);  if (sleep_mode > 2) sleep_mode = 1;
                cfg_logi      = (uint8_t)((ld.misc_a >> 12) & 1u);
                cfg_boot_heat = (uint8_t)((ld.misc_a >> 13) & 1u);
                cfg_boot_anim = (uint8_t)((ld.misc_a >> 14) & 1u);
                fly_enable    = (uint8_t)((ld.misc_a >> 15) & 1u);
                fly_dur       = (uint8_t)((ld.misc_b >> 29) & 1u);
                cfg_motion_th = (int)((ld.misc_a >> 16) & 0xFFu);   if (cfg_motion_th < 5 || cfg_motion_th > 100) cfg_motion_th = 30;
                cfg_idle_s    = (uint8_t)(ld.misc_b & 0xFFu);       if (cfg_idle_s < 1 || cfg_idle_s > 250) cfg_idle_s = 30;
                cfg_pause_s   = (uint8_t)((ld.misc_b >> 8) & 0xFFu);  if (cfg_pause_s < 1 || cfg_pause_s > 250) cfg_pause_s = 30;
                cfg_sleep_min = (uint8_t)((ld.misc_b >> 16) & 0xFFu); if (cfg_sleep_min < 1 || cfg_sleep_min > 250) cfg_sleep_min = 10;
                cfg_theme     = (uint8_t)((ld.misc_b >> 24) & 3u);   /* 0/1/2 预设，3=COL 自定义 */
                apply_theme();
                cfg_preset[0] = (int)(int16_t)(ld.preset01 & 0xFFFFu);
                cfg_preset[1] = (int)(int16_t)((ld.preset01 >> 16) & 0xFFFFu);
                cfg_preset[2] = (int)(int16_t)(ld.preset2 & 0xFFFFu);
                for (int pi = 0; pi < 3; pi++)
                    if (cfg_preset[pi] < TEMP_MIN_C || cfg_preset[pi] > TEMP_MAX_C) cfg_preset[pi] = 320 + pi * 30;
                /* ★ v228: 一次性迁移旧默认值（80% / 12s），之后用户再改不会被覆盖 */
                if (!(ld.misc_b & (1u << 26)) && cfg_motion_th == 80) { cfg_motion_th = 30; cfg_migrated = 1; }
                if (!(ld.misc_b & (1u << 27)) && cfg_idle_s == 12)    { cfg_idle_s = 30;    cfg_migrated = 1; }
                if (!(ld.misc_b & (1u << 28)) && cfg_pause_s == 5)    { cfg_pause_s = 30;   cfg_migrated = 1; }
            }
            /* ★ v254: PID 参数（默认就是自调的 2.00/0.010/1.00；兼容旧 tag） */
            if ((ld.pid_tag >> 16) == 0x504Bu) {
                uint32_t chk = (ld.pid_p100 ^ ld.pid_i1000 ^ ld.pid_d100 ^ 0x504Bu) & 0xFFFFu;
                if ((ld.pid_tag & 0xFFFFu) == chk &&
                    ld.pid_p100 <= 9999u && ld.pid_i1000 <= 9999u && ld.pid_d100 <= 9999u) {
                    pid_kp = (float)ld.pid_p100 / 100.0f;
                    pid_ki = (float)ld.pid_i1000 / 1000.0f;
                    pid_kd = (float)ld.pid_d100 / 100.0f;
                }
            } else if ((ld.pid_tag >> 16) == 0x504Au) {
                uint32_t chk = (ld.pid_p100 ^ ld.pid_i1000 ^ ld.pid_d100 ^ 0x504Au) & 0xFFFFu;
                if ((ld.pid_tag & 0xFFFFu) == chk &&
                    ld.pid_p100 <= 9999u && ld.pid_i1000 <= 9999u && ld.pid_d100 <= 9999u) {
                    /* v253 设计基线刻度记录 → 换回内部等效增益，并标记重存 */
                    pid_kp = (float)ld.pid_p100 / 500.0f;
                    pid_ki = (float)ld.pid_i1000 / 300.0f;
                    pid_kd = (float)ld.pid_d100 / 2000.0f;
                    cfg_migrated = 1;
                }
            } else if ((ld.pid_tag >> 16) == 0x5049u) {
                uint32_t chk = (ld.pid_p100 ^ ld.pid_i1000 ^ ld.pid_d100 ^ 0x5049u) & 0xFFFFu;
                if ((ld.pid_tag & 0xFFFFu) == chk &&
                    ld.pid_p100 <= 9999u && ld.pid_i1000 <= 9999u && ld.pid_d100 <= 9999u) {
                    pid_kp = (float)ld.pid_p100 / 100.0f;
                    pid_ki = (float)ld.pid_i1000 / 1000.0f;
                    pid_kd = (float)ld.pid_d100 / 100.0f;
                    cfg_migrated = 1;
                }
            }
            /* ★ v251: COL 自定义调色板 */
            if ((ld.col_tag >> 16) == 0x434Fu) {
                uint32_t chk = (ld.col01 ^ ld.col23 ^ ld.col45) & 0xFFFFu;
                if ((ld.col_tag & 0xFFFFu) == chk) {
                    cfg_col[0] = (uint16_t)(ld.col01 & 0xFFFFu);
                    cfg_col[1] = (uint16_t)(ld.col01 >> 16);
                    cfg_col[2] = (uint16_t)(ld.col23 & 0xFFFFu);
                    cfg_col[3] = (uint16_t)(ld.col23 >> 16);
                    cfg_col[4] = (uint16_t)(ld.col45 & 0xFFFFu);
                    cfg_col[5] = (uint16_t)(ld.col45 >> 16);
                    col_ok = 1;
                }
            }
            if (cfg_theme == 3 && !col_ok) cfg_theme = 0;
            apply_theme();
        }
    }
    {
        fly_meta_t bm;
        if (flash_meta_load(&bm)) {
            fly_last_crc64 = bm.crc64;
            fly_last_id_ok = 1;
        }
    }
    if (cfg_migrated) save_ok = settings_save_now();   /* 持久化迁移标记 */
    draw_main(25.0f, 0);                      /* v227: 用已加载设置重画滑入目标帧 */
    ui_dirty = 1;
    uint32_t last_btn = 0, last_ctrl = 0, last_draw = 0, last_pd = 0, last_acc = 0;
    last_activity_ms = millis();   /* 按键或运动都算“在用”，菜单里操作不会触发暂停链 */
    uint32_t boot_t0 = millis();
    int bl_prev = 0, br_prev = 0, bc_prev = 0;
    uint32_t last_fast = 0;
    uint32_t last_pdread = 0;
    uint32_t last_pd_retry = 0;
    uint32_t bc_t0 = 0, rep_t = 0;
    int rep_n = 0, bc_long_fired = 0;
    uint32_t combo_t0 = 0;
    static uint8_t wd_fails = 0;          /* v32: 鐪嬮棬鐙楄繛缁け璐ヨ鏁?(閫€閬跨敤) */

    for (;;) {
        uint32_t now = millis();
        poll_current(now);
        current_window_tick(now);
        if (fly_clear_t0 && now - fly_clear_t0 >= 250u) { fly_clear_t0 = 0; ui_dirty = 1; }

        /* 娓╁害闆剁偣: 涓婄數 1.5s 鍚庨噰 32 娆″钩鍧?(閬垮紑涓婄数婕傜Щ) */
        if (!t_zero_done && now - boot_t0 >= T_ZERO_DELAY) {
            uint32_t acc = 0;
            for (int i = 0; i < 32; i++) acc += adc_temp();
            t_offset = (uint16_t)(acc / 32);
            t_zero_done = 1;
            ui_dirty = 1;
        }

        if (now - last_btn >= 10) {
            last_btn = now;
            /* ★ v110: 按键唤醒 — 深度/待机/休眠任意档 → 恢复加热态; 清全部计时 */
            if (btn_left() || btn_right() || btn_centre()) {
                sleep_ctr = 0;
                last_motion_ms = now;   /* ★ v203: 任何按键=在使用，静置重新计 */
                last_activity_ms = now; /* ★ v223: 同时刷新暂停链，菜单里按键不关加热 */
                /* ★ v249: asleep 已置位但 dev_state 还没来得及切 SLEEP 时也要取消睡眠 */
                if (asleep || dev_state >= DS_SLEEP) {
                    if (dev_state >= DS_SLEEP) dev_state = wake_dev_state();
                    asleep = 0; idle_cnt = 0; motion_run = 0;
                    last_motion_ms = now; last_activity_ms = now; ui_dirty = 1;
                    /* ★ v197: 本次按下仅用于唤醒 —— 吞掉，不触发任何原按键动作 */
                    bl_prev = btn_left(); br_prev = btn_right(); bc_prev = btn_centre();
                    /* ★ v249: 同时清掉连发/双击状态，避免按住唤醒键时下一拍触发连发 */
                    rep_t = now; rep_n = 0;
                    dbl_side = 0; dbl_t = 0; br_dbl_arm = 0;
                    g_btn_hold = 0;
                    bc_t0 = 0;
                    continue;
                }
            }
            int bl = btn_left(), br = btn_right(), bc = btn_centre();
            if (bc) { if (!bc_long_fired && g_btn_hold < 60000u) g_btn_hold += 10u; }
            else { g_btn_hold = 0; pdo_apply_ok = 0; }

            if (bl && !bl_prev) {
                dbl_side = 0; dbl_t = 0;          /* v233: 左键打断右键双击序列 */
                if (page == 1) pdo_move(-1);
                else act_left();
                rep_t = now; rep_n = 0; ui_dirty = 1;
            } else if (bl && bl_prev && now - rep_t >= (rep_n ? 17u : 83u)) {   /* v233: 500ms 后每 100ms 连发 */
                if (page == 1) pdo_move(-1);
                else act_left();
                rep_n++; rep_t = now; ui_dirty = 1;
            }
            if (br && !br_prev) {
                br_t0 = now;
                if (page == 1) pdo_move(1);
                else if (page == 0) {
                    /* ★ v233: 第二击先只“预备”，短按松手才切常用温度；长按仍然是连发调温 */
                    if (dbl_side == 2 && (uint32_t)(now - dbl_t) < DBL_TICKS) {
                        br_dbl_arm = 1;
                    } else { act_temp_inc(); dbl_side = 2; dbl_t = now; }
                }
                else act_right();
                rep_t = now; rep_n = 0; ui_dirty = 1;
            } else if (br && br_prev && now - rep_t >= (rep_n ? 17u : 83u)) {   /* v233: 长按连发 */
                if (page == 1) pdo_move(1);
                else act_right();
                rep_n++; rep_t = now; ui_dirty = 1;
            }
            if (!br && br_prev && br_dbl_arm) {
                if (page == 0 && rep_n == 0 && now - br_t0 < CLICK_MAX_MS) {
                    preset_idx = (uint8_t)((preset_idx + 1u) % 3u);
                    act_temp_set(cfg_preset[preset_idx]);
                    dbl_side = 0; dbl_t = 0;
                }
                br_dbl_arm = 0;
            }
            if (bc && !bc_prev) {
                bc_t0 = now; bc_long_fired = 0;
                dbl_side = 0; dbl_t = 0;          /* v233: 中键打断双击序列 */
                if (page == 17) rst_done_t0 = 0;
            }
            /* ★ v28: PDO 页 左+中 同按 0.3s → LM 页 */
            if (page == 1 && bl && bc) {
                if (combo_t0 == 0) combo_t0 = now;
                if (now - combo_t0 >= 50u && !bc_long_fired) {
                    bc_long_fired = 1; combo_t0 = 0; g_btn_hold = 0;
                    ui_go(2, 1);
                }
            } else combo_t0 = 0;
            unsigned lp_ms = (page == 0) ? 400u : (page == 1) ? LONG_PRESS_APPLY
                           : (page == 17) ? 250u : LONG_PRESS_MS;
            bc_hold_hint = (page == 1 && bc && bc_t0 && now - bc_t0 >= LONG_PRESS_APPLY / 2) ? 1 : 0;
            if (bc && bc_prev && bc_t0 && !bc_long_fired && now - bc_t0 >= lp_ms) {
                bc_long_fired = 1; g_btn_hold = 0;
                if (page == 0) {
                    /* ★ v224: 进菜单立即停止加热；退出菜单也保持停止，需重新按键加热 */
                    heat_on = 0; tip_paused = 0; duty_now = 0; pwm_set(0);
                    menu_sel = 0;
                    menu_anim_t0 = 0;
                    menu_pos_from = menu_pos_to = 0;
                    menu_view_from = menu_view_to = 0;
                    ui_go(10, 1); bc_t0 = 0; bc_hold_hint = 0;
                } else if (page == 10) {
                    int np = (menu_sel == 0) ? 1 : (12 + menu_sel - 1);
                    if (np == 12) { set_edit = 0; preset_edit_i = 0; }
                    ui_go(np, 1); bc_t0 = 0;
                } else if (page == 12) {
                    if (set_edit && set_sel == 10 && fly_sel == 3) {
                        fly_clear_ok = flash_fly_clear();
                        fly_i = 0;
                        if (fly_clear_ok) { fly_last_id_ok = 0; fly_last_crc64 = 0; }
                        fly_clear_t0 = now;
                        ui_dirty = 1;
                    } else {
                        int entering = !set_edit;
                        if (!entering && set_sel == 10) fly_commit();
                        set_edit = !set_edit;
                        if (entering) {
                            set_flash_t0 = now;
                            set_anim_t0 = 0;
                            set_pos_from = set_pos_to = (int16_t)(set_sel * 1000);
                            set_view_from = set_view_to = (int16_t)(set_view_of(set_sel) * 1000);
                        }
                        if (entering && set_sel == 10) fly_sel = (uint8_t)(fly_enable ? (fly_dur ? 2 : 1) : 0);
                        if (set_edit && set_sel == 11) preset_edit_i = 0;
                    }
                    bc_t0 = 0;
                } else if (page == 17) {
                    settings_defaults();
                    rst_done_t0 = now;
                    bc_t0 = 0;
                } else if (page == 13) {   /* v135: 设计基线语义 — 长按选中校准点并自动加热 */
                    if (!cal_adj) {
                        cal_adj = 1;
                        if (dev_state != DS_NO_TIP) { target_c = CAL_PTS[cal_idx]; heat_on = 1; }
                    } else { cal_adj = 0; heat_on = 0; }
                    bc_t0 = 0;
                } else if (page == 14) {
                    if (pid_test_view) {
                        pid_test_view = 0; heat_on = 0; duty_now = 0; pwm_set(0);
                    } else if (pid_edit) {
                        pid_edit = 0;
                    } else if (pid_sel == 4) {
                        save_ok = settings_save_now();
                        pid_saved_t0 = now;
                    } else if (pid_sel == 5) {
                        heat_on = !heat_on;
                        if (heat_on) { pid_pv_prev = (float)dbg_temp_c; pid_test_view = 1; }
                        else { duty_now = 0; pwm_set(0); pid_test_view = 0; }
                    } else {
                        pid_edit = 1;
                        pid_adj_t = 0; pid_adj_run = 0;
                        pid_anim_t0 = 0;
                        pid_pos_from = pid_pos_to = (int16_t)(pid_sel * 1000);
                        pid_view_from = pid_view_to = (int16_t)(pid_view_of(pid_sel) * 1000);
                    }
                    bc_t0 = 0;
                } else if (page == 15) {
                    if (col_edit) {
                        col_edit = 0;
                    } else {
                        col_edit = 1; col_ch = 0;
                        col_adj_t = 0; col_adj_run = 0;
                    }
                    bc_t0 = 0;
                } else if (page == 1) {
                    /* ★ v24 对齐设计基线: 红挡(充电器不广播)时无动作, 只有绿挡可应用 */
                    if ((pdo_ok_mask & (1 << pdo_sel)) &&
                        now - last_apply >= APPLY_COOLDOWN) {
                        pdo_gear = pdo_sel;
                        husb238_select_request(pdo_gear);
                        save_ok = settings_save_now();
                        last_apply = now;
                        g_btn_hold = LONG_PRESS_APPLY;   /* 本帧进度条刚好 100% */
                        pdo_apply_ok = 1;
                    }
                }
                ui_dirty = 1;
            }
            if (!bc && bc_prev) {
                if (bc_t0 && !bc_long_fired && now - bc_t0 < CLICK_MAX_MS) {
                    if (page == 0 && now >= main_click_guard_until) heat_on = !heat_on;
                    else if (page == 1) ui_go(10, -1);
                    else if (page == 2) ui_go(1, -1);
                    else if (page == 10) ui_go(0, -1);
                    else if (page == 13) { if (cal_adj) { cal_adj = 0; heat_on = 0; } else ui_go(10, -1); }
                    else if (page == 14) {
                        if (pid_test_view) { pid_test_view = 0; heat_on = 0; duty_now = 0; pwm_set(0); }
                        else if (pid_edit) pid_edit = 0;
                        else ui_go(10, -1);
                    }
                    else if (page == 15) {
                        if (col_edit) {
                            /* R→G→B→退出编辑，和 SET 多值项的短按循环一致 */
                            if (++col_ch >= 3u) { col_ch = 0; col_edit = 0; }
                            col_adj_t = 0; col_adj_run = 0;
                        } else ui_go(10, -1);
                    }
                    else if (page == 12) {
                        if (set_edit) {
                            if (set_sel == 11) { preset_edit_i = (uint8_t)((preset_edit_i + 1u) % 3u); if (preset_edit_i == 0) set_edit = 0; }
                            else {
                                if (set_sel == 10) fly_commit();
                                set_edit = 0;
                            }
                        } else ui_go(10, -1);
                    }
                    else if (page == 17) ui_go(10, -1);
                    else if (page >= 12) ui_go(10, -1);
                    ui_dirty = 1;
                }
                bc_t0 = 0;
            }
            if (page == 1 && bl && br && !bl_prev && !br_prev) {
                lcd_set_orientation(lcd_get_orientation() + 1); ui_dirty = 1;   /* 鏂瑰悜 O0-O7 寰幆 */
            }
            /* ★ v018: 改过设置后松手就落盘，避免 2s 内断电丢最后一项 */
            if ((!bl && bl_prev) || (!br && br_prev)) {
                if (settings_key_dirty) {
                    settings_key_dirty = 0;
                    save_at = 0;
                    save_ok = settings_save_now();
                    ui_dirty = 1;
                }
            }
            bl_prev = bl; br_prev = br; bc_prev = bc;
        }

        /* 鍔犻€熷害 50Hz (v23: 鎶楀櫔澹扮炕杞?鈥?闇€杩炵画 ROT_SUSTAIN 鎷嶇ǔ瀹氳秴闃堝€? 骞虫斁/寰姩涓嶇炕) */
        /* ★ v55: 20ms 级 attach 快速检测 + 上电恢复 (设计基线级响应) */
        if (!boot_apply_done && husb_ack && now - last_fast >= 3u) {
            last_fast = now;
            pd_att = (husb238_read(0x01) & 0x40) ? 1 : 0;
            if (pd_att && (pdo_ok_mask & 1) && now >= 50u) {
                husb238_select_request(pdo_gear);
                boot_apply_done = 1;
                last_apply = now;
                ui_dirty = 1;
            }
        }
        /* ★ v258: 先等方向确定再启动开机画面；最多等 500ms，避免旧版按默认方向显示 */
        if (!boot_bl_on) {
            uint32_t waited = (uint32_t)(now - boot_t0) * MS_PER_TICK;
            if (!boot_orient_ok && waited < 500u) {
                /* 背光保持熄灭，等下面的加速度计重试给出方向 */
            } else {
                if (cfg_bright < 100) lcd_dim_pct(cfg_bright);   /* 首帧就按保存亮度显示 */
                if (cfg_boot_anim) {
                    lcd_boot_reveal();
                    /* READY 留在 GRAM 作为旧画面；fb 重画主界面后从黑底斜切进入 */
                    draw_main(25.0f, 0);
                    ui_slide = 1;
                    ui_slide_ready = 1;
                    ui_slide_pm = 0;
                    ui_slide_boot = 1;
                    ui_slide_stable = 0;
                    ui_slide_last = millis();
                    ui_anim_t0 = millis();
                } else { lcd_flush(); lcd_backlight_on(); }   /* 无动画：先把主界面送 GRAM 再开背光 */
                boot_bl_on = 1;
                ui_dirty = 1;
            }
        }
        /* ★ v259: 开机画面出现前每 100ms 重试，直到方向确定；
         *   出现后恢复 500ms 重试（仅传感器未就绪/方向未定时） */
        if ((!accel_ready || !boot_orient_ok) && now - last_acc_init >= (boot_bl_on ? 83u : 17u)) {
            last_acc_init = now;
            i2c_scan();
            if (accel_init()) {
                int8_t bx = 0, by = 0, bz = 0;
                accel_read_xyz(&bx, &by, &bz);
                if (bx || by || bz) {
                    accel_ready = 1;
                    boot_orient_sample(bx, by, bz);
                }
            }
        }
        /* ★ v174: 旋转检测 40Hz 立即生效 —— 10Hz+2拍确认(≈400ms)用户反馈太慢 */
        if (now - last_rot >= 50u) {   /* v193: 25->50ms，40Hz 的 I2C 读把主循环拖到 2Hz */
            last_rot = now;
            int8_t rx, ry, rz;
            accel_read_xyz(&rx, &ry, &rz);
            /* ★ v176: 180° 平分判定 —— 以 gz 过零（屏幕竖直）为界，两侧各留 20 的回差
             *   正放 gz≈+70 / 反放 gz≈-55 → 转过半圈点才翻，不会动一点点就回正 */
            /* ★ v209: 整秒触发重绘 —— 静置秒表规整跳格（数值在绘制时现算，绝不漏拍） */
            {
                int idle_s = (int)((uint32_t)(now - last_motion_ms) * MS_PER_TICK / 1000u);
                if (idle_s != last_idle_shown) { last_idle_shown = idle_s; ui_dirty = 1; }
            }
            /* ★ v178: 判据 = gx（水平转向角）
             *   轨迹实测：翻转时 gx 在 -54..+65 之间摆，gz 全程为正（屏幕一直朝上）
             *   → 屏幕翻转对应的是"笔在水平面内转过去"，不是绕长轴翻滚
             *   用户演示的触发角 = gx≈-27 → 阈值取 ±25，中间 50 宽的死区天然带迟滞
             *   gy 门限（±40）：低头焊接时重力压到长轴，此时不参与判断 */
            (void)rz;
            if (cfg_rot_mode == 1) {          /* ★ v181: 左手 → rot180=0（实测方向反了，互换） */
                if (rot180 != 0) { rot180 = 0; lcd_set_rot180(0); ui_dirty = 1; }
            } else if (cfg_rot_mode == 2) {   /* ★ v181: 右手 → rot180=1 */
                if (rot180 != 1) { rot180 = 1; lcd_set_rot180(1); ui_dirty = 1; }
            } else if (ry < 40 && ry > -40) { /* 自动：按 gx 水平转向判定 */
                if (rx > 25 && rot180 != 1)       { rot180 = 1; lcd_set_rot180(1); ui_dirty = 1; }
                else if (rx < -25 && rot180 != 0) { rot180 = 0; lcd_set_rot180(0); ui_dirty = 1; }
            }
        }
        if (now - last_acc >= 7) {   /* ★ v253: ~25Hz，对齐设计基线 SC7A20 采样节拍 */
            last_acc = now;
            int16_t ax, ay, az;
            /* ★ v253: 用 12bit mg 读数（raw>>4）做运动判据，阈值为设置值本身 */
            if (accel_read_mg(&ax, &ay, &az)) {
                /* ★ v171: 轨迹记录（按高字节等价缩放，保持 int8 日志） */
                {
                    uint16_t k = acc_i % ACC_N;
                    acc_log[k][0] = (int8_t)(ax / 16);
                    acc_log[k][1] = (int8_t)(ay / 16);
                    acc_log[k][2] = (int8_t)(az / 16);
                    acc_log[k][3] = (int8_t)rot180;
                    if (acc_i < 60000) acc_i++;
                }
                {
                    static int16_t lx = 0, ly = 0, lz = 0; static uint8_t li = 0;
                    static uint8_t hall_on_n = 0, hall_off_n = 0, activity_run = 0;
                    int dx = ax - lx, dy = ay - ly, dz = az - lz;
                    if (dx < 0) dx = -dx;
                    if (dy < 0) dy = -dy;
                    if (dz < 0) dz = -dz;
                    /* 全 0/超量程样本跳过；静止时重力不可能三轴全 0 */
                    int valid = !(ax == 0 && ay == 0 && az == 0)
                             && !(ax > 2000 || ax < -2000 || ay > 2000
                                  || ay < -2000 || az > 2000 || az < -2000);
                    if (!li) {
                        if (valid) { lx = ax; ly = ay; lz = az; li = 1; }
                    } else {
                        dbg_gx = ax; dbg_gy = ay; dbg_gz = az;
                        dbg_motion = (uint16_t)(dx + dy + dz);
                        int bad = !valid;
                        if (!bad) {
                            uint16_t motion = (uint16_t)(dx + dy + dz);
                            /* ★ v253: 设计基线语义 —— 运动阈值直接以 mg 比较，连续 3 拍确认 */
                            uint16_t activity_th = (uint16_t)cfg_motion_th;
                            if (motion >= activity_th) { if (activity_run < 6) activity_run++; }
                            else activity_run = 0;
                            int motion_active = (activity_run >= 5);   /* ★ v255: 5 拍抗噪，防静止误清零 */
                            if (motion_active) last_activity_ms = now;
                            if (!asleep) {
                                if (motion_active) {
                                    last_motion_ms = now; idle_cnt = 0;
                                } else if (sleep_mode == 1) {
                                    motion_run = 0;
                                    uint32_t iv = (uint32_t)(now - last_activity_ms) * MS_PER_TICK;
                                    dbg_idle = (uint16_t)(iv / 1000u);
                                    if (dbg_idle != last_idle_shown) { last_idle_shown = (int)dbg_idle; ui_dirty = 1; }
                                    if (!fly_enable && iv >= (uint32_t)cfg_idle_s * 1000u) {
                                        asleep = 1; idle_cnt = 0; motion_run = 0; activity_run = 0;
                                        sleep_guard_t0 = now;
                                    }
                                    if (idle_cnt < 250) idle_cnt++;
                                } else if (sleep_mode == 2) {
                                    motion_run = 0;
                                    if (hall_active()) {
                                        if (hall_on_n < 3) hall_on_n++;
                                        if (!fly_enable && hall_on_n >= 3) {
                                            asleep = 1; idle_cnt = 0; motion_run = 0; activity_run = 0;
                                            sleep_guard_t0 = now;
                                            heat_on = 0; tip_paused = 0;
                                            ui_dirty = 1;
                                        }
                                    } else {
                                        hall_on_n = 0;
                                        last_motion_ms = now;
                                    }
                                } else { motion_run = 0; idle_cnt = 0; last_motion_ms = now; }
                            } else {
                                if (now - sleep_guard_t0 < 167u) {
                                    motion_run = 0; hall_off_n = 0; activity_run = 0;
                                } else if (sleep_mode == 2) {
                                    if (!hall_active()) {
                                        if (++hall_off_n >= 2u) {
                                            hall_off_n = 0; asleep = 0; idle_cnt = 0; motion_run = 0; activity_run = 0;
                                            last_motion_ms = now; last_activity_ms = now;
                                            if (dev_state >= DS_SLEEP) { dev_state = wake_dev_state(); ui_dirty = 1; }
                                        }
                                    } else hall_off_n = 0;
                                } else {
                                    /* ★ v253: 设计基线唤醒判据 —— 阈值直接比较，连续 3 拍 */
                                    uint16_t wake_th = (uint16_t)cfg_motion_th;
                                    if (motion >= wake_th) {
                                        if (++motion_run >= 3u) {
                                            asleep = 0; idle_cnt = 0; motion_run = 0; activity_run = 0;
                                            last_motion_ms = now; last_activity_ms = now;
                                            if (dev_state >= DS_SLEEP) { dev_state = wake_dev_state(); ui_dirty = 1; }
                                        }
                                    } else motion_run = 0;
                                }
                            }
                            dbg_asleep = asleep; dbg_idle = idle_cnt;
                        }
                        if (!bad) { lx = ax; ly = ay; lz = az; }
                    }
                }
            }
        }

        /* PDO 骞挎挱鍒锋柊: PDO 椤?2Hz, 鍏朵粬椤?0.5Hz + 涓婄數鑷姩鎭㈠璇遍獥鎸′綅 */
        /* ★ v229: HUSB238 如果启动时没应答，主循环每 0.5s 重扫一次直到找到 */
        if (!husb_ack && now - last_pd_retry >= 83u) {
            last_pd_retry = now;
            i2c_scan();
            husb_ack = (i2c_ack[1] & (1 << 0)) != 0;
            if (husb_ack) { pdo_mask_refresh(); last_pd = 0; if (page == 1) ui_dirty = 1; }
        }
        if (page == 1 ? (now - last_pd >= 167u) : (now - last_pd >= 333u)) {   /* v218: 1s / 2s 真实 */
            last_pd = now;
            pd = husb_ack ? husb238_read(0x00) : 0;
            pd_att = husb_ack && (husb238_read(0x01) & 0x40) ? 1 : 0;   /* attach 浣?*/
            pdo_ma_sel = husb_ack ? husb238_pdo_ma((uint8_t)pdo_gear) : 0;
            vin_raw = adc_vin();
            pdo_mask_refresh();
            if (!(pdo_ok_mask & 1)) {
                for (int t = 0; t < 5 && !(pdo_ok_mask & 1); t++) pdo_mask_refresh();
            }
            /* ★ v50: 三种写法轮换自检 — style 轮换 (0=1字节 1=10字节连写 2=GO脉冲), 显示 回读
             * 用户可对照 V 是否跟随: 哪种 style 让电压变化 = 该芯片接受的写法 */
            /* v54: M 诊断探针移除 (三种写法均可用, 写入从来不是问题) */
            /* 涓婄數鑷姩鎭㈠: PD attach 鍚庤嚜鍔ㄨ姹備繚瀛樼殑鎸′綅 (v23: 20ms 蹇€熻疆璇? 涓嶅啀绛?2s 鍧? */
            if (!boot_apply_done && husb_ack && pd_att && (pdo_ok_mask & 1) && now >= 50u) {   /* v218: 50 tick = 300ms */
                husb238_select_request(pdo_gear);
                boot_apply_done = 1;
                last_apply = now;
                if (page == 1) ui_dirty = 1;
            }
            /* 鈽?v31 鎸′綅鐪嬮棬鐙?+ v32 閫€閬? 鍗忓晢 鈮?鎵€閫?鈫?閲嶆柊璇锋眰;
             * 杩炵画 5 娆¤嚜鎰堝け璐?鈫?鑺傛祦 10s/娆?(鏈夌晫鎸崱, 涓嶆寔缁獨鎵扮數婧?, 鎴愬姛鍗虫竻闆?*/
            if (husb_ack && pd_att && boot_apply_done &&
                (pdo_ok_mask & (1 << pdo_gear)) &&
                ((pd >> 4) & 0xF) != (uint8_t)(pdo_gear + 1) &&
                now - last_apply >= (wd_fails >= 5 ? 1667u : 500u)) {   /* v218: 10s / 3s 真实 */
                husb238_select_request(pdo_gear);
                last_apply = now;
                if (wd_fails < 250) wd_fails++;
                if (page == 1) ui_dirty = 1;
            }
            if (((pd >> 4) & 0xF) == (uint8_t)(pdo_gear + 1)) wd_fails = 0;   /* 鑷剤鎴愬姛娓呴浂 */
            if (page == 1) ui_dirty = 1;
        }

        /* 璁剧疆淇濆瓨 (2s 闃叉姈) */
        if (save_at && now >= save_at) {
            save_at = 0;
            save_ok = settings_save_now();
            ui_dirty = 1;
        }

        /* 调参版：停止加热时自动把黑匣子落盘，避免拔热头 */
        {
            static uint8_t fly_heat_prev = 0;
            if (fly_heat_prev && !heat_on) fly_save_now();
            fly_heat_prev = heat_on;
        }

        /* 娓╂帶 20Hz (v21: vin_raw 涔熷湪姝ら噰鏍? V 琛?50ms 鍐呮洿鏂? */
        if (now - last_ctrl >= 10) {
            last_ctrl = now;
            /* ★ v60: PD 协商电压 10Hz 快读 (原 1s 块太慢, 跟不上右上角 ADC 电压) */
            if (husb_ack && now - last_pdread >= 17u) {   /* v218: 17 tick ≈ 100ms → 10Hz */
                last_pdread = now;
                pd = husb238_read(0x00);
            }
            uint16_t raw_now = adc_temp_win();   /* ★ v100: 窗口采样 */
            /* 设计基线：加热中 raw 3101..3999 属于超范围故障，退出加热 */
            {
                static uint8_t hot_fault_cnt = 0;
                if (raw_now > TEMP_RAW_VALID_MAX && raw_now < TIP_RAW_THRESHOLD) {
                    if (hot_fault_cnt < 10) hot_fault_cnt++;
                } else hot_fault_cnt = 0;
                if (hot_fault_cnt >= 3 && heat_on) {
                    heat_on = 0; duty_now = 0; pwm_set(0);
                }
            }
            /* ★ v130: 拔头检测改为「连续 3 拍」去抖（30ms）— 加热噪声单点尖峰不再误判无头
             * 之前 v128 单点 ≥3501 就 hist_fill 立即生效 → 3711 的噪声尖峰触发了两次假三角 */
            if (raw_now >= TIP_RAW_THRESHOLD) {
                if (tip_gone_cnt < 10) tip_gone_cnt++;
            } else {
                tip_gone_cnt = 0;
                last_good_temp = raw_now;
            }
            uint16_t t_raw;
            if (tip_gone_cnt >= 3) {
                t_raw = 4095;                                     /* 连续 3 拍开路 → 确认无头 */
                if (g_hist_n < 8) g_hist_n = 8;                   /* 允许刷屏显示三角 */
            } else {
                /* 噪声尖峰：用上次好值参与滤波，尖峰不影响显示 */
                t_raw = hist_avg(raw_now >= TIP_RAW_THRESHOLD ? last_good_temp : raw_now);
            }
            /* ★ v249: 捕捉“无头→有头”插入沿（睡眠/待机中也重置显示，不改变睡眠状态） */
            {
                int tip_open = (t_raw >= TIP_RAW_THRESHOLD);
                if (!tip_open && tip_was_open) {
                    /* 新头插入不是真实温度变化 —— 丢掉旧头温度历史，用当前读数重建显示 */
                    uint16_t fresh = (raw_now < TIP_RAW_THRESHOLD) ? raw_now : last_good_temp;
                    hist_fill(fresh);
                    t_raw = fresh;
                    pid_pv_prev = (float)adc_to_c(t_raw);
                    disp_reset_req = 1;
                    tip_r_dmR = 0xFFFF;   /* ★ v273: 等第一次加热电流再测冷态内阻 */
                    rs_latched = 0;
                }
                tip_was_open = (uint8_t)tip_open;
            }
            /* ★ v90: 烙铁头插入检测（TC 开路 = ADC 饱和）+ 状态机 + 休眠 */
            if (t_raw >= TIP_RAW_THRESHOLD) {
                tip_present_cnt = 0;
                /* ★ v249: 休眠/待机/深度都不允许拔头检测重置状态链 */
                if (dev_state != DS_NO_TIP && dev_state < DS_SLEEP) {
                    dev_state = DS_NO_TIP; duty_now = 0; pid_i = 0; last_err = 0;
                    tip_r_dmR = 0xFFFF; rs_latched = 0;   /* ★ v273: 拔头清空内阻，下次插入重测 */
                    /* ★ v126: 拔头瞬间把黑匣子落盘 — PWLink 插拔会断电，SRAM2 会丢 */
                    fly_save_now();
                }
            } else if (dev_state == DS_NO_TIP) {
                /* ★ v260: 上电 ADC 未稳定（t_zero 前）不判插头；
                 *   稳定后连续 3 拍有效才认为插头，避免主界面先闪一下 25 */
                if (t_zero_done) {
                    if (tip_present_cnt < 6) tip_present_cnt++;
                    if (tip_present_cnt >= 3) dev_state = DS_READY;
                }
            } else {
                tip_present_cnt = 0;
            }
            /* ★ v021: 黑匣子开启期间不休眠；已睡下则立即唤醒（不改 sleep_mode，关掉后恢复原休眠档） */
            if (fly_enable && asleep) {
                asleep = 0; idle_cnt = 0; motion_run = 0;
                ui_dirty = 1;
            }
            /* ★ v234: 无烙铁头也能休眠；睡下后拔头检测不要把它拉回 NO_TIP */
            /* ★ v250: 兜底 —— 醒着却停留在 SLEEP/STANDBY/DEEP 属非法状态，强拉回 READY；
             *   避免出现“醒来后一直无法再次休眠”的卡死。 */
            if (!asleep && dev_state >= DS_SLEEP) dev_state = wake_dev_state();
            if (asleep && (dev_state == DS_READY || dev_state == DS_NO_TIP)) {
                dev_state = DS_SLEEP;
                heat_on = 0; tip_paused = 0;   /* v242: 睡下即停热，唤醒后不自动恢复 */
            }
            /* ★ v86: 窗口诊断采样 (相位分桶) */
            dbg_win_duty = duty_now;
            win_diag_sample(t_raw);
            float cur = adc_to_c(t_raw);
            vin_raw = adc_vin();
            /* ★ v121: 内阻测量 — R = VBUS/I（有电流时），零额外脉冲
             * ★ v273: 每次插头只取第一次有效加热电流锁存，避免看到热态值 */
            if (!rs_latched && iout_raw > 400 && vin_raw > 1000) {
                uint32_t duty_pct = (uint32_t)duty_now * 100u / PWM_MAX;
                uint32_t r_mR = (uint32_t)((uint32_t)vin_raw * 693 / 4096) * 100000u
                              / ((uint32_t)iout_raw * I_MA_PER_RAW / 1000);
                r_mR = r_mR * duty_pct / 100u;   /* 平均电流 → 导通内阻 */
                if (r_mR > 100 && r_mR < 30000) {
                    tip_r_dmR = (uint16_t)(r_mR / 100);
                    rs_latched = 1;
                }
            }
            /* ★ v117b: 诊断快照更新 */
            dbg_raw = t_raw; dbg_temp_c = (uint16_t)(cur + 0.5f);
            dbg_state_m = dev_state; dbg_target = target_c;
            /* ★ v125: 显示温度 — 放宽下限（210 板室温 raw 可能 <19）+ 斜率限制 */
            if (t_raw <= 3050) {
                /* v241: 显示温度做 4 点滑动平均；不再用 ±30℃ 门限，否则一次跳变后会把显示永久锁死 */
                static uint16_t dq[4];
                static uint8_t qi = 0, qn = 0;
                int reset = disp_reset_req;
                disp_reset_req = 0;
                uint16_t nt;
                if (reset) {
                    /* v249: 以当前原始读数填满滤波队列，旧头温度不再参与 */
                    nt = (uint16_t)(adc_to_c(raw_now) + 0.5f);
                    for (int k = 0; k < 4; k++) dq[k] = nt;
                    qi = 0; qn = 4;
                } else {
                    nt = (uint16_t)(cur + 0.5f);
                    if (!qn) { for (int k = 0; k < 4; k++) dq[k] = nt; qn = 4; }
                    else { dq[qi] = nt; qi = (uint8_t)((qi + 1) & 3); }
                }
                uint32_t sum = 0;
                for (int k = 0; k < 4; k++) sum += dq[k];
                g_disp_temp = (uint16_t)(sum / 4);
                if (reset) {
                    /* ★ v272: 插头插入直接落位当前室温，不再从旧显示值逐度滚上来 */
                    disp_roll_init = 1;
                    disp_val = (int)g_disp_temp;
                    disp_roll_to = disp_val;
                    disp_roll_active = 0;
                    disp_roll_t0 = millis();
                    disp_roll_last = disp_roll_t0;
                }
            }
            /* ★ v256: 休眠期间温度继续采样，但显示值冻结在绘制层；
             *   这里同步 disp_val，唤醒时直接显示降温后的真实温度，而不是睡前旧值 */
            if (dev_state >= DS_SLEEP) {
                disp_val = (int)g_disp_temp;
                disp_roll_to = disp_val;
                disp_roll_active = 0;
                disp_roll_init = 1;
            }
            {
                /* v232: 大变化立即起一帧，让加热爬升能连续滚动；±1 噪声不触发 */
                static uint16_t last_temp_seen = 0;
                static uint32_t last_temp_ui = 0;
                if ((uint16_t)g_disp_temp != last_temp_seen) {
                    int dv = (int)g_disp_temp - (int)last_temp_seen;
                    if (dv < 0) dv = -dv;
                    last_temp_seen = (uint16_t)g_disp_temp;
                    if (dv >= 1 && (page == 0 || page == 13) && now - last_temp_ui >= 17u) {
                        last_temp_ui = now;
                        ui_dirty = 1;
                    }
                }
            }
            if (dbg_win_mode == 2) { duty_now = dbg_win_fix; }   /* ★ v87: 诊断强制占空比 */
            else if (heat_on && dev_state == DS_READY && !tip_paused && pd_att && t_raw < OVERTEMP_RAW && iout_raw < OVERI_RAW) {
                int d = pid_step(t_raw);          /* ★ v107: 设计基线 PID, 返回 0-100% */
                if (d > limit_pct) d = limit_pct;  /* ★ v107: LM 功率限制恢复 (百分比对百分比) */
                duty_now = (uint16_t)((uint32_t)d * PWM_MAX / 100);   /* 0-100% → 0..319 内部量程 */
            } else {
                duty_now = 0; pid_i = 0; last_err = 0;
            }
            if (dbg_win_mode == 2) duty_now = dbg_win_fix;
            pwm_set(duty_now);
            /* 飞行记录 — PD245 调参版 60ms/点，受 fly_enable 控制（默认关）
             * v014: 移到 PWM 更新之后，记录的 duty 与本拍温度同相 */
            if (fly_enable && heat_on) {
                static uint8_t fly_div = 0;
                if (++fly_div >= FLY_DIV) {
                    fly_div = 0;
                    uint16_t fly_n = FLY_LEN();
                    if (fly_i < fly_n) {
                        uint16_t fidx = fly_i & (FLY_N - 1);
                        FLY_R[fidx] = t_raw;
                        FLY_T[fidx] = (uint16_t)cur;
                        FLY_D[fidx] = duty_now;
                        fly_i++;
                    }
                    if (fly_i >= fly_n) {
                        /* ★ v019: 到 FULL 自动停热；下一拍 save-on-stop 落盘 */
                        heat_on = 0; tip_paused = 0; duty_now = 0; pwm_set(0);
                        fly_full_t0 = millis();
                    }
                }
            }
            /* ★ v233: 对齐设计基线 — 静置→休眠(黄)，暂停时间(s)→待机(蓝)，休眠时间(min)→深度 */
            {
                static uint16_t div1s = 0;
                static uint16_t prog = 0;
                if (++div1s >= 17) {           /* 控制环 10 tick(60ms) × 17 ≈ 1s */
                    div1s = 0;
                    /* v234: 主循环兜底休眠，避免传感器任务偶发卡住时永远不睡 */
                    if (sleep_mode == 1 && !asleep && !fly_enable &&
                        (uint32_t)(now - last_activity_ms) * MS_PER_TICK >= (uint32_t)cfg_idle_s * 1000u) {
                        asleep = 1; idle_cnt = 0; motion_run = 0; sleep_guard_t0 = now;
                    }
                    if (dev_state == DS_SLEEP) {
                        if (++prog >= (uint16_t)cfg_pause_s) { prog = 0; dev_state = DS_STANDBY; ui_dirty = 1; }
                    } else if (dev_state == DS_STANDBY) {
                        if (++prog >= (uint16_t)cfg_sleep_min * 60u) { prog = 0; dev_state = DS_DEEP; ui_dirty = 1; }
                    } else {
                        prog = 0;
                    }
                }
            }
        }

        /* ★ v217: 智能刷新节拍 — 滑动/动画 16ms(≈60fps) / 常态 50ms */
        uint32_t fms = ui_frame_ms(now);
        if (now - last_draw >= fms || ui_dirty) {
            last_draw = now;
            ui_dirty = 0;
            /* ★ v123: 用控制环滤波后的显示温度，不再直读裸 ADC（消除 0℃ 闪烁） */
            float cur = (float)g_disp_temp;
            /* ★ v128: 采样未满 8 拍前不刷屏，避免上电闪一下室温 */
            if (g_hist_n >= 8) {
                if (!(ui_slide && ui_slide_ready)) {
                    int st = 0;
                    if (heat_on && duty_now) st = 2;
                    else if (heat_on) st = 1;
                    if (page == 0) draw_main(cur, st);
                    else if (page == 1) draw_pdo();
                    else if (page == 2) draw_limit();
                    else if (page == 10) draw_menu();
                    else if (page == 13) draw_cal();
                    else if (page == 12) draw_set();
                    else draw_menu_page(page);
                    if (ui_slide) { ui_slide_ready = 1; ui_anim_t0 = now; }
                }
                ui_present();
            }
        }
    }
}
